import { sampleHoldings, sampleNames, makeDemoCandles } from '/demo.js';
import { analyzeCandles, analyzeDerivative, validateCandles } from '/engine.js';
import { analyzeLongTerm } from '/longterm.js';
import { migrateWorkspace, holdingKey, scopeHoldings, aggregatePortfolio, replaceAccountHoldings } from '/portfolio.js';
import { planPosition, evaluateChecklist, analyzeDrift } from '/research.js';

const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = (n,d=0) => Number.isFinite(n) ? '₹'+n.toLocaleString('en-IN',{minimumFractionDigits:d,maximumFractionDigits:d}) : '—';
const num = (n,d=1) => Number.isFinite(n) ? n.toLocaleString('en-IN',{maximumFractionDigits:d}) : '—';
const signed = (n,d=2) => Number.isFinite(n) ? `${n>=0?'+':''}${n.toFixed(d)}%` : '—';
const sourceLabel = s => ({demo:'Synthetic sample',csv:'CSV · unverified',manual:'Manual · no prices',kite:'Kite',groww:'Groww'}[s] || s);
const iconPaths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',wallet:'M3 7h17v13H3z M3 7V4h14v3 M15 12h7v5h-7z',chart:'M3 17l5-5 4 3 8-10 M15 5h5v5 M3 21h18',layers:'M12 3 2 8l10 5 10-5-10-5 M2 12l10 5 10-5 M2 16l10 5 10-5',plug:'M8 2v5 M16 2v5 M5 7h14v3a7 7 0 0 1-14 0V7 M12 17v5',book:'M12 5C8 2 4 3 2 4v16c3-2 7-2 10 0 3-2 7-2 10 0V4c-3-2-6-2-10 1z M12 5v15',arrow:'M5 12h14 M14 7l5 5-5 5',up:'M5 17 17 5 M5 5h12v12',down:'M5 7l7 7 7-7',plus:'M12 5v14 M5 12h14',upload:'M12 16V3 M7 8l5-5 5 5 M3 16v5h18v-5',download:'M12 3v13 M7 11l5 5 5-5 M3 17v4h18v-4',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 1 0 0-18 M12 7v5l3 2',info:'M12 3a9 9 0 1 0 0 18 9 9 0 1 0 0-18 M12 11v6 M12 7v1',check:'M5 12l4 4L19 6',close:'M6 6l12 12 M6 18 18 6',refresh:'M20 7v5h-5 M4 17v-5h5 M5 7a8 8 0 0 1 14 0 M19 17a8 8 0 0 1-14 0',search:'M10 3a7 7 0 1 0 0 14 7 7 0 1 0 0-14 M16 16l5 5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 1 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',more:'M5 11v2 M12 11v2 M19 11v2',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6l-9-4 M8 12l3 3 5-6',spark:'M12 2l2.4 7.6L22 12l-7.6 2.4L12 22l-2.4-7.6L2 12l7.6-2.4z',menu:'M4 6h16 M4 12h16 M4 18h16',external:'M14 3h7v7 M10 14 21 3 M21 14v7H3V3h7',edit:'m14 4 6 6 M3 21l5-1L21 7 17 3 4 16l-1 5',trash:'M3 6h18 M8 6V3h8v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7'};
const ico = (name,cls='') => `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.chart}"/></svg>`;
const saved=(()=>{try{return JSON.parse(localStorage.getItem('stocklens.v2')||localStorage.getItem('stocklens.v1')||'{}')}catch{return {}}})();
const migrated=migrateWorkspace(saved,sampleHoldings);
const state={...migrated,tab:'overview',settings:{horizon:'swing',riskPercent:.5,accountSize:100000,...saved.settings},research:saved.research||{},targets:saved.targets||{},selected:migrated.selected||null,period:'3M',search:'',opFilter:'all'};
const runtime={credentials:{},connectionEpoch:{},quotes:{},brokerCandles:{},lastFetch:null,busy:false,fno:{broker:'kite',accountId:null,query:'',results:[],contract:null,quote:null,candles:[],underlying:null,error:null,lastHistory:0},auto:true};
state.source=state.accounts.find(a=>'account:'+a.id===state.scope)?.broker||'combined';
const demoData=Object.fromEntries(sampleHoldings.map(h=>[h.symbol,makeDemoCandles(h.symbol)]));
function key(h){return holdingKey(h);}

function persist(){try{localStorage.setItem('stocklens.v2',JSON.stringify({version:2,accounts:state.accounts,members:state.members,scope:state.scope,holdings:state.holdings,imported:state.imported,theses:state.theses,research:state.research,targets:state.targets,settings:state.settings,source:state.source}));}catch{toast('Browser storage is full. Export your holdings before closing.',true);}}

function visibleHoldings(){return scopeHoldings(state.holdings,state.accounts,state.scope);}

function selected(){let h=visibleHoldings().find(h=>key(h)===state.selected);if(!h){h=visibleHoldings()[0];state.selected=h?key(h):null;}return h;}

function candlesFor(h){if(!h)return [];return h.source==='demo'?demoData[h.symbol]||[]:state.imported[key(h)]?.candles||runtime.brokerCandles[key(h)]?.candles||[];}
function provenance(h){const c=candlesFor(h),entry=state.imported[key(h)]||runtime.brokerCandles[key(h)];return {source:state.imported[key(h)]?'csv':h.source,isDemo:h.source==='demo',isStale:state.imported[key(h)]?true:h.source==='csv'||h.source==='manual'?true:entry?.isStale??true,asOf:entry?.asOf||c.at(-1)?.time,horizon:state.settings.horizon,lastBarComplete:true};}

function analysis(h){return analyzeCandles(candlesFor(h),h?{...provenance(h),...(state.tab==='swing'?{horizon:'swing'}:{})}:{});}
function quoteFor(h){const q=runtime.quotes[key(h)];const bars=candlesFor(h),last=bars.at(-1),prev=bars.at(-2);if(q)return {...q,isStale:q.isStale||!q.timestamp||Date.now()-Date.parse(q.timestamp)>90000};if(Number.isFinite(h.lastPrice)&&(!last||Date.parse(h.priceAsOf)>Date.parse(last.time)))return {price:h.lastPrice,timestamp:h.priceAsOf,isStale:true};return {price:last?.close,changePercent:last&&prev?(last.close/prev.close-1)*100:undefined,timestamp:last?.time,volume:last?.volume,isStale:h.source!=='demo'};}

function dateTime(t,short=false){if(!t||!Number.isFinite(Date.parse(t)))return 'Not available';return new Date(t).toLocaleString('en-IN',{timeZone:'Asia/Kolkata',day:'2-digit',month:'short',...(short?{}:{year:'numeric',hour:'2-digit',minute:'2-digit'})});}
function sourcePill(s){return `<span class="source-pill ${esc(s)}">${s==='demo'?'SAMPLE':esc(s==='manual'?'MANUAL':s)}</span>`;}
function logo(h){return `<span class="stock-logo ${h.symbol==='TCS'?'blue':h.symbol==='INFY'?'purple':h.symbol==='HDFCBANK'?'red':''}">${esc(h.symbol==='RELIANCE'?'R':h.symbol.slice(0,1))}</span>`;}
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='toast'+(error?' error':'');el.style.display='block';clearTimeout(runtime.toastTimer);runtime.toastTimer=setTimeout(()=>el.style.display='none',6500);}
function setTab(tab){state.tab=tab;if(tab==='family'&&state.source==='demo')setScope('all',false);if(tab==='swing')state.settings.horizon='swing';state.search='';render();window.scrollTo({top:0,behavior:'smooth'});}
function mainTitle(){return {family:['ONE FAMILY. A COMPLETE VIEW.','Every account. One perspective.','Combine demat accounts, understand overlap and keep each family member’s holdings clear.'],research:['A MORE CONSIDERED DECISION','Plan the risk. Record the reason.','Position sizing, evidence checklists and allocation reviews using your own assumptions.'],swing:['DAYS TO WEEKS','A plan for the next market move.','Daily trend, volume confirmation and conditional price levels.'],longterm:['MONTHS TO YEARS','Give every investment a thesis.','Review business evidence and your own valuation assumptions, separately from trading signals.'],overview:['YOUR INVESTING WORKSPACE','Your portfolio, in perspective.','Understand what you own. See what deserves a closer look.'],portfolio:['A CLEARER PICTURE','Every holding. A little more clarity.','Import your portfolio and review the evidence behind each position.'],fno:['DERIVATIVES RESEARCH','A setup is only as good as its evidence.','Daily underlying direction. Contract liquidity. A defined risk budget.'],opportunities:['YOUR RESEARCH SHORTLIST','Find the next stock worth studying.','Rank your available price histories using transparent technical rules.'],connections:['YOUR DATA, CONNECTED','Bring your portfolio into focus.','Connect a supported broker or use the free CSV workflow with any platform.'],methodology:['BUILT TO BE UNDERSTOOD','Transparent rules. Clear boundaries.','See exactly how StockLens reaches an assessment.']}[state.tab];}
function render(){const h=selected();const title=mainTitle();const sources=[...new Set(state.holdings.map(h=>h.source||'csv'))];$('#app').innerHTML=`<a class="skip-link" href="#main-content">Skip to content</a><div class="layout"><button class="nav-backdrop" data-action="close-menu" aria-label="Close navigation" hidden></button><aside class="sidebar" id="workspace-navigation"><div class="brand"><svg class="brandmark" viewBox="0 0 32 34" fill="none" aria-hidden="true"><path d="M3 28V14h6v14M13 28V6h6v22M23 28V1h6v27" stroke="currentColor" stroke-width="3"/><path d="M1 32h30" stroke="currentColor" stroke-width="2"/></svg><span class="brand-name">stocklens<span class="brand-dot">.</span></span><button class="icon-btn sidebar-close" data-action="close-menu" aria-label="Close navigation">${ico('close')}</button></div><div class="workspace-label">Workspace</div><nav class="nav" aria-label="Main navigation">${[['overview','grid','Overview'],['portfolio','wallet','Portfolio'],['family','layers','Family & accounts'],['swing','chart','Swing analysis'],['longterm','clock','Long-term'],['fno','chart','Intraday / F&O'],['opportunities','layers','Opportunities'],['research','shield','Research desk'],['connections','plug','Connections'],['methodology','book','Methodology']].map(([id,i,t])=>`${id==='swing'?'<div class="nav-group">Research</div>':id==='connections'?'<div class="nav-group">Workspace</div>':''}<button data-nav="${id}" class="${state.tab===id?'active':''}" title="${t}" aria-label="${t}" ${state.tab===id?'aria-current="page"':''}>${ico(i)}<span class="nav-label">${t}</span>${id==='fno'?'<span class="new-tag">BETA</span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="data-note"><strong><span class="dot"></span>Clarity before conviction</strong><p>Research with transparent rules.<br>You stay in control of every decision.</p></div><div class="profile"><div class="avatar">SL</div><div><strong>Family workspace</strong><span>Free · stored on this device</span></div><button class="icon-btn chevron" data-action="settings" aria-label="Open preferences">${ico('settings')}</button></div></div></aside><main class="main" id="main-content" tabindex="-1"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Open navigation" aria-controls="workspace-navigation" aria-expanded="false">${ico('menu')}</button>Workspace <span>/</span> <strong>${{overview:'Overview',portfolio:'Portfolio',family:'Family & accounts',research:'Research desk',swing:'Swing analysis',longterm:'Long-term',fno:'Intraday / F&O',opportunities:'Opportunities',connections:'Connections',methodology:'Methodology'}[state.tab]}</strong></div><div class="topbar-right"><span class="session-label"><span class="dot"></span>${state.source==='demo'?'Sample workspace':runtime.lastFetch?'Last fetch '+dateTime(runtime.lastFetch,true):'No live feed connected'}</span><span class="date-label">${new Date().toLocaleDateString('en-IN',{timeZone:'Asia/Kolkata',day:'numeric',month:'short',year:'numeric'})}</span><button class="icon-btn" data-action="settings" aria-label="Workspace preferences">${ico('settings')}</button></div></header><section class="heading"><div><div class="eyebrow">${title[0]} ${state.source==='demo'?'<span class="demo-pill">DEMO</span>':''}</div><h1>${title[1]}</h1><p class="subtitle">${title[2]}</p></div><div class="heading-actions"><button class="btn" data-action="import-holdings">${ico('upload')}Import CSV</button><button class="btn btn-primary" data-action="connect">${ico('plug')}<span>Connect broker</span></button></div></section>${!['methodology','connections','family','research'].includes(state.tab)?`<div class="source-banner">${ico('info')}<span>${state.source==='demo'?'<strong>You’re exploring sample data.</strong> All prices, holdings and signals in this workspace are synthetic.':state.source==='csv'||state.source==='manual'?'<strong>Imported data workspace.</strong> CSV prices are unverified and never marked live. Analysis is for research.':`<strong>${esc(scopeLabel())}.</strong> Data is fetched on demand and polled when connected. Freshness is shown per quote.`}</span><button data-nav="connections">Use your own data ${'↗'}</button></div>`:''}${!['connections','methodology'].includes(state.tab)?scopeBar():''}${state.tab==='family'?renderFamily():state.tab==='research'?renderResearch():state.tab==='overview'?renderOverview(h):state.tab==='portfolio'?renderPortfolio(h):state.tab==='swing'?renderSwing(h):state.tab==='longterm'?renderLongterm(h):state.tab==='fno'?renderFno():state.tab==='opportunities'?renderOpportunities():state.tab==='connections'?renderConnections():renderMethodology()}<footer class="bottom-note"><span>${ico('shield')}Independent research, not investment advice. Rules can fail. No orders are placed by StockLens.</span><span>Made for a more considered investor.</span></footer></main></div>`;bindChart();}

function summary(){const hs=visibleHoldings(),total=aggregatePortfolio(hs,quoteFor,state.accounts,state.members);let prev=0,watch=0;for(const h of hs){const q=quoteFor(h);if(Number.isFinite(q.price))prev+=q.price*h.quantity/(1+(q.changePercent||0)/100);if(analysis(h).score>=60)watch++;}return {current:total.currentValue,cost:total.pricedInvestment,prev,priced:total.pricedCount??hs.filter(h=>Number.isFinite(quoteFor(h).price)).length,count:hs.length,watch,pnl:total.pnl,pnlPct:total.pnlPercent,change:prev?(total.currentValue-prev)/prev*100:0};}

function stats(){const s=summary();return `<div class="stat-grid"><article class="stat-card"><div class="stat-label">Portfolio value ${ico('wallet')}</div><div class="stat-value">${s.priced?money(s.current):'—'}</div><div class="stat-bottom">${s.priced?`<span class="mini-badge ${s.change<0?'red':''}">${signed(s.change)}</span> last available session`:'Import prices to calculate'}${s.priced<s.count?` · ${s.priced}/${s.count} priced`:''}</div></article><article class="stat-card"><div class="stat-label">Unrealised return ${ico('chart')}</div><div class="stat-value">${s.priced?(s.pnl>=0?'+':'−')+money(Math.abs(s.pnl)):'—'}</div><div class="stat-bottom"><span class="${s.pnl>=0?'positive':'negative'}">${s.priced?signed(s.pnlPct):'No priced holdings'}</span>${s.priced?' on '+money(s.cost)+' invested':''}</div></article><article class="stat-card"><div class="stat-label">Tracked stocks ${ico('layers')}</div><div class="stat-value">${s.count}<span class="unit">stocks</span></div><div class="stat-bottom"><span class="dot" style="background:#a5b88c"></span>${s.priced} with price history · ${s.count-s.priced} awaiting data</div></article><article class="stat-card"><div class="stat-label">Bullish watchlist ${ico('spark')}</div><div class="stat-value">${s.watch}<span class="unit">to research</span></div><div class="stat-bottom"><span class="mini-badge amber">RULE BASED</span> score of +60 or higher</div></article></div>`;}
function researchModes(){return `<div class="research-modes" aria-label="Choose a research horizon">${[['swing','chart','Swing analysis','Days to weeks'],['longterm','clock','Long-term investing','Months to years'],['fno','layers','Intraday / F&O','Direction, volume & risk']].map(([tab,icon,title,caption])=>`<button class="research-mode" data-nav="${tab}">${ico(icon)}<span><strong>${title}</strong><small>${caption}</small></span>${ico('arrow','mode-arrow')}</button>`).join('')}</div>`;}
function renderOverview(h){return `${stats()}${researchModes()}<div class="workspace-grid"><div>${chartCard(h)}${holdingsTable(false)}</div>${analysisCard(h)}</div>${opportunitiesPreview()}`;}
function renderSwing(h){return `<div class="strategy-strip"><div><span class="tag">SWING</span><h2>5–15 trading sessions</h2><p>An illustrative review window. Reassess sooner if the scenario fails.</p></div><button class="btn" data-nav="fno">Intraday / F&O ${ico('arrow')}</button><button class="btn" data-nav="longterm">Long-term thesis ${ico('arrow')}</button></div><div class="workspace-grid">${chartCard(h)}${analysisCard(h)}</div>${holdingsTable(true)}`;}
function renderLongterm(h){
 if(!h)return `<section class="card">${empty('book','Start with a company.','Add a stock before recording a long-term thesis.','add-holding','Add a stock')}</section>`;
 const t=state.theses[key(h)]||{},q=quoteFor(h);
 const a=analyzeLongTerm({price:q.price,priceSource:h.source,priceAsOf:q.timestamp,thesis:t});
 const field=(name,label,type='number',fallback='',extra='')=>`<div class="form-row"><label for="thesis-${name}">${label}</label><input id="thesis-${name}" name="${name}" type="${type}" value="${esc(t[name]??fallback)}" ${type==='number'?'step="any"':''} ${extra}></div>`;
 return `<section class="card content-card"><div class="section-heading"><div><h2>${esc(h.symbol)} · investment thesis</h2><p>Evidence you enter from company filings. Your criteria, visible in one place.</p></div><select id="chart-symbol" aria-label="Stock for long-term review">${visibleHoldings().map(x=>`<option value="${esc(key(x))}" ${key(x)===key(h)?'selected':''}>${esc(x.symbol)}</option>`).join('')}</select></div><div class="strategy-strip"><div><span class="signal-pill ${a.status==='hold-for-review'?'':'wait'}">${{'needs-evidence':'MORE EVIDENCE NEEDED','review-thesis':'REVIEW YOUR THESIS','hold-for-review':'WITHIN YOUR CRITERIA · REVIEW REGULARLY'}[a.status]}</span><p>${esc(a.horizon?.label||'Set a planned holding window below.')} · a plan, not an estimate of future returns.</p></div><strong>${money(q.price,2)}<small class="cell-secondary">${esc(sourceLabel(h.source))} · ${dateTime(q.timestamp)}</small></strong></div><div class="two-col"><form id="thesis-form" data-id="${esc(key(h))}"><div class="form-row"><label for="thesis-notes">Why own this business? What would change your mind?</label><textarea id="thesis-notes" name="notes" rows="4" required placeholder="Business advantage, expected growth drivers, and reasons to exit…">${esc(t.notes||'')}</textarea></div><div class="form-grid">${field('sourceUrl','Company filing / evidence URL','url','','required')}${field('sourceDate','Report date','date','','required')}${field('reviewDate','Next review date','date','','required')}${field('fairValue','Your fair value per share (₹)','number','','min="0.01" required')}${field('earningsGrowth','Reported earnings growth (%)')}${field('minGrowth','Your minimum earnings growth (%)','number',0)}${field('debtEquity','Reported debt / equity ratio')}${field('maxDebt','Your maximum debt / equity','number',1,'min="0"')}${field('minMonths','Planned minimum months','number',12,'min="1" max="120"')}${field('maxMonths','Planned maximum months','number',36,'min="1" max="120"')}</div><div class="form-row"><label for="thesis-cashflow">Reported operating cash flow positive?</label><select id="thesis-cashflow" name="cashFlowPositive"><option value="">Unknown / not checked</option><option value="true" ${t.cashFlowPositive===true?'selected':''}>Yes</option><option value="false" ${t.cashFlowPositive===false?'selected':''}>No</option></select></div><button class="btn btn-primary" type="submit">${ico('check')}Save & review thesis</button></form><div><h3 style="margin-top:0">Your review checklist</h3><ul class="blocker-list">${a.checks.map(c=>`<li class="check-${c.status}"><strong>${c.status==='pass'?'✓':c.status==='fail'?'!':'○'} ${esc(c.label)}</strong><br>${esc(c.detail)}</li>`).join('')}</ul><div class="note-box">${a.valuationUpside==null?'No valid valuation comparison yet.':`Your fair-value assumption is ${signed(a.valuationUpside)} relative to this price. This is arithmetic from your input, not forecast upside.`}</div><p>Review after each earnings release and whenever your thesis changes. Missing evidence or breached criteria calls for research, not an automatic sale.</p><p>These general ratios may be unsuitable for banks, insurers and some sectors. Adjust your criteria and verify comparable reporting periods. StockLens does not fetch or verify company fundamentals.</p></div></div></section>`;
}

function renderPortfolio(h){return `${stats()}${holdingsTable(true)}<div class="workspace-grid small-section">${chartCard(h)}${analysisCard(h)}</div>`;}
function chartCard(h){if(!h)return `<section class="card">${empty('wallet','Your portfolio starts here.','Add a holding or import a CSV to begin.','add-holding','Add a holding')}</section>`;const q=quoteFor(h),bars=candlesFor(h);return `<section class="card chart-card"><div class="card-head"><h2 class="card-title">Performance overview</h2><div class="source-filter"><select id="chart-symbol" aria-label="Selected chart stock">${visibleHoldings().map(x=>`<option value="${esc(key(x))}" ${key(h)===key(x)?'selected':''}>${esc(x.symbol)}</option>`).join('')}</select></div></div><div class="chart-header"><div class="stock-identity">${logo(h)}<div><div class="stock-name">${esc(h.symbol)} ${sourcePill(h.source)}</div><div class="stock-meta">${esc(h.name||sampleNames[h.symbol]?.name||h.symbol)} · ${esc(h.exchange)}</div></div></div><div class="stock-price">${money(q.price,2)}<span class="stock-change ${q.changePercent<0?'negative':'positive'}">${signed(q.changePercent)} <span class="last-session">last session</span></span></div></div><div class="chart-toolbar"><div class="segmented" aria-label="Chart period">${['1M','3M','6M','ALL'].map(p=>`<button data-period="${p}" class="${state.period===p?'active':''}" aria-pressed="${state.period===p}">${p}</button>`).join('')}</div><div class="legend"><span><i></i>Close price</span><span><i class="vol"></i>Volume</span></div></div>${bars.length?`<div class="chart-wrap" id="price-chart">${chartSVG(bars)}<div class="chart-tooltip" id="chart-tooltip"></div></div>`:'<div class="empty-chart">No price history for this holding.<br>Import daily OHLCV or connect its broker.</div>'}<div class="chart-footer"><span>${h.source==='demo'?'Synthetic · ':state.imported[key(h)]?'Unverified CSV · ':'Completed daily bars · '}${bars.length?dateTime(bars.at(-1).time):'Awaiting data'}${h.source!=='demo'&&bars.length?' IST':''}</span><button data-action="import-candles">${ico('upload')}Import OHLCV</button></div></section>`;}
function getChartBars(bars){return bars.slice(-({'1M':22,'3M':65,'6M':130,ALL:100000}[state.period]));}
function chartSVG(input,w=760){const bars=getChartBars(input),h=250,pad={l:9,r:62,t:17,b:25};const min=Math.min(...bars.map(b=>b.low)),max=Math.max(...bars.map(b=>b.high)),span=max-min||max*.03;const low=min-span*.08,high=max+span*.08;const x=i=>pad.l+i/Math.max(1,bars.length-1)*(w-pad.l-pad.r),y=p=>pad.t+(high-p)/(high-low)*158;const pts=bars.map((b,i)=>`${x(i).toFixed(2)},${y(b.close).toFixed(2)}`);const vMax=Math.max(...bars.map(b=>b.volume),1);const grid=Array.from({length:4},(_,i)=>{const v=low+(high-low)*i/3,yy=y(v);return `<line x1="${pad.l}" y1="${yy}" x2="${w-pad.r+6}" y2="${yy}" stroke="#e2ebe7" stroke-dasharray="3 4"/><text x="${w-pad.r+16}" y="${yy+3}" fill="#637b73" font-size="10">${num(v,0)}</text>`;}).join('');const labels=[0,Math.round((bars.length-1)/3),Math.round((bars.length-1)*2/3),bars.length-1].map(i=>`<text x="${x(i)}" y="242" fill="#637b73" font-size="10" text-anchor="${i===0?'start':i===bars.length-1?'end':'middle'}">${dateTime(bars[i].time,true)}</text>`).join('');return `<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img" aria-label="${esc(selected()?.symbol||'')} close prices with daily volume; source ${esc(state.source)}"><defs><linearGradient id="price-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#46b091" stop-opacity=".25"/><stop offset="100%" stop-color="#a8dac6" stop-opacity=".02"/></linearGradient></defs>${grid}<path d="M${pts[0]} L${pts.join(' L')} L${x(bars.length-1)},190 L${x(0)},190 Z" fill="url(#price-fill)"/><polyline points="${pts.join(' ')}" fill="none" stroke="#13846d" stroke-width="2.3" vector-effect="non-scaling-stroke"/>${bars.map((b,i)=>`<rect x="${x(i)-Math.max(.7,(w-pad.r)/bars.length*.28)}" y="${222-b.volume/vMax*30}" width="${Math.max(1,(w-pad.r)/bars.length*.56)}" height="${b.volume/vMax*30}" fill="${i>bars.length-8?'#79b9a1':'#cde3d8'}" rx=".7"/>`).join('')}<circle cx="${x(bars.length-1)}" cy="${y(bars.at(-1).close)}" r="3.2" fill="#13846d" stroke="white" stroke-width="2"/><line id="chart-crosshair" x1="0" y1="10" x2="0" y2="224" stroke="#a0b38e" stroke-dasharray="3 3" visibility="hidden"/>${labels}</svg>`;}
function bindChart(){
 const wrap=$('#price-chart');if(!wrap)return;
 const redraw=()=>{const chart=wrap.querySelector('svg');if(chart)chart.outerHTML=chartSVG(candlesFor(selected()),Math.max(240,wrap.clientWidth-24));};redraw();
 wrap.onpointermove=e=>{const h=selected(),bars=getChartBars(candlesFor(h));if(!bars.length)return;const chart=wrap.querySelector('svg'),r=chart.getBoundingClientRect(),w=chart.viewBox.baseVal.width;const xx=(e.clientX-r.left)/r.width*w,i=Math.max(0,Math.min(bars.length-1,Math.round((xx-9)/(w-9-62)*(bars.length-1)))),b=bars[i],t=$('#chart-tooltip');t.innerHTML=`<strong>${dateTime(b.time,true)} · ${h.source==='demo'?'SAMPLE':esc(h.source.toUpperCase())}</strong><br>Close ${money(b.close,2)}<br>Volume ${num(b.volume,0)}`;t.style.display='block';t.style.left=Math.max(5,Math.min(wrap.clientWidth-165,e.clientX-wrap.getBoundingClientRect().left+13))+'px';t.style.top='12px';const line=$('#chart-crosshair');line.setAttribute('x1',String(9+i/Math.max(1,bars.length-1)*(w-9-62)));line.setAttribute('x2',line.getAttribute('x1'));line.setAttribute('visibility','visible');};wrap.onpointerleave=()=>{$('#chart-tooltip').style.display='none';$('#chart-crosshair').setAttribute('visibility','hidden');};
}
window.addEventListener?.('resize',()=>{clearTimeout(runtime.chartResize);runtime.chartResize=setTimeout(()=>{bindChart();if(window.innerWidth>900)toggleMenu(false,false);},150);});
function analysisCard(h){const a=h?analysis(h):null,ind=a?.indicators||{},valid=a?.valid;const bullish=a?.score>=60,bearish=a?.score<=-60;return `<aside class="card analysis-card"><div class="card-head"><div class="analysis-head"><span class="sparkle">${ico('spark')}</span><h2 class="card-title">The StockLens view</h2></div>${ico('more')}</div><div class="analysis-body"><div class="analysis-signal"><span class="signal-pill ${bearish?'negative':bullish?'':'wait'}">${!valid?'AWAITING DATA':bullish?'BULLISH WATCHLIST':bearish?'BEARISH WATCHLIST':'HOLD FOR REVIEW'}</span></div><p class="analysis-copy">${!valid?esc(a?.errors?.[0]||'Add at least 20 completed daily bars to see a transparent assessment.'):bullish?`<strong>${esc(h.symbol)}</strong> shows a positive technical trend. Review its volume and risk conditions before considering any entry.`:bearish?`<strong>${esc(h.symbol)}</strong> shows a weakening technical trend. Revisit your thesis and review its risk levels.`:`<strong>${esc(h.symbol)}</strong> has mixed directional evidence. Wait for a clearer setup and revisit your original investment thesis.`}</p><div class="horizon-box">${ico('clock')}<div><span>Suggested review horizon</span><strong>${state.settings.horizon==='swing'?'5–15 trading sessions':'20–60 trading sessions'}</strong></div></div><div class="analysis-line"><span>Directional rule score</span><b>${valid?`${a.score>0?'+':''}${a.score}`:'—'} <span style="color:#a0ac90;font-weight:400">/ ±100</span></b></div><div class="meter">${Array.from({length:10},(_,i)=>`<i class="${valid&&i<Math.round(Math.abs(a.score)/10)?'on':''}"></i>`).join('')}</div><div class="analysis-details"><div class="analysis-line"><span>Volume vs prior 20 bars</span><b>${num(ind.volumeRatio,2)}${ind.volumeRatio!=null?'×':''}</b></div><div class="analysis-line"><span>RSI · 14 sessions</span><b>${num(ind.rsi14,1)}</b></div><div class="analysis-line"><span>20-day average</span><b>${money(ind.sma20,2)}</b></div><div class="analysis-line"><span>Scenario invalidation</span><b>${money(a?.trade?.stop,2)}</b></div><div class="analysis-line"><span>Setup eligibility</span><b>${a?.trade?.allowed?'Rules passed':'Blocked / review only'}</b></div></div><div class="analysis-foot">${h?.source==='demo'?'Sample data cannot qualify as a trade. ':h?.source==='csv'?'CSV data is unverified. ' :''}Review sooner if the scenario invalidates. A review horizon is not a promise of returns or a fixed holding period.</div><button class="text-link" style="margin-top:12px" data-action="analysis-details">View rules & conditions ${ico('arrow')}</button></div></aside>`;}
function holdingsTable(full){const hs=visibleHoldings().filter(h=>!state.search||`${h.symbol} ${h.name||''}`.toLowerCase().includes(state.search.toLowerCase()));return `<section class="card holdings-card" ${full?'style="margin-top:0"':''}><div class="card-head"><div><h2 class="card-title">Tracked stocks <span style="font-size:9px;color:#a2ad96;font-weight:400">${visibleHoldings().length}</span></h2><p class="card-caption">A closer look at the stocks you own.</p></div><div class="table-tools"><input id="holdings-search" aria-label="Search holdings" placeholder="Search holdings…" value="${esc(state.search)}"><button class="btn btn-small" data-action="add-holding">${ico('plus')}Add holding</button>${full?`<button class="btn btn-small" data-action="export">${ico('download')}Export</button>`:''}</div></div><div class="table-wrap"><table><thead><tr><th>Stock</th><th class="numeric">Last price</th><th class="numeric">Current value</th><th class="numeric">Unrealised P&L</th><th>Research view</th>${full?'<th>Review horizon</th>':''}<th></th></tr></thead><tbody>${hs.map(h=>holdingRow(h,full)).join('')||`<tr><td colspan="7"><div class="empty-state">${state.search?'No holdings match your search.':'No holdings in this workspace. Import a CSV or add your first stock.'}</div></td></tr>`}</tbody></table></div><div class="table-footer"><span>${state.source==='demo'?'Illustrative portfolio · synthetic prices':esc(sourceLabel(state.source))+' · prices may be missing or delayed'}</span><button class="text-link" ${full?'data-action="add-holding"':'data-nav="portfolio"'}>${full?'Add a holding':'View full portfolio'} ${ico('arrow')}</button></div></section>`;}
function holdingRow(h,full){const q=quoteFor(h),a=analysis(h),value=q.price*h.quantity,profit=value-h.average_price*h.quantity,pct=(q.price/h.average_price-1)*100;return `<tr data-select="${esc(key(h))}" class="${state.selected===key(h)?'selected':''}"><td><div class="table-company">${logo(h)}<div><button class="stock-name-button" data-select="${esc(key(h))}" aria-label="View ${esc(h.symbol)} analysis" aria-pressed="${state.selected===key(h)}">${esc(h.symbol)}</button><small class="account-tag">${esc(accountLabel(h))}</small><small>${h.quantity===0?'Research watchlist · no position':num(h.quantity,4)+' shares · '+money(h.average_price,2)+' avg.'}</small></div></div></td><td class="numeric">${money(q.price,2)}<span class="cell-secondary ${q.changePercent<0?'negative':'positive'}">${signed(q.changePercent)}</span></td><td class="numeric">${money(value)}<span class="cell-secondary">${q.timestamp?dateTime(q.timestamp):'No market data'}${['kite','groww'].includes(h.source)?(q.isStale?' · STALE':' · recent quote'):''}</span></td><td class="numeric ${profit<0?'negative':'positive'}">${Number.isFinite(profit)?(profit>=0?'+':'−')+money(Math.abs(profit)):'—'}<span class="cell-secondary ${profit<0?'negative':'positive'}">${signed(pct)}</span></td><td><span class="mini-badge ${a.score<=-60?'red':a.score>=60?'':'amber'}">${!a.valid?'NEEDS DATA':a.score>=60?'BULLISH WATCHLIST':a.score<=-60?'BEARISH WATCHLIST':'HOLD / REVIEW'}</span></td>${full?`<td>${state.settings.horizon==='swing'?'5–15':'20–60'} sessions<span class="cell-secondary">or sooner at invalidation</span></td>`:''}<td><button class="row-action" data-edit="${esc(key(h))}" aria-label="Edit ${esc(h.symbol)} holding">${ico('more')}</button></td></tr>`;}
function ranked(){return visibleHoldings().map(h=>({h,a:analysis(h)})).filter(x=>x.a.valid).sort((a,b)=>b.a.score-a.a.score);}
function opportunitiesPreview(){const rows=ranked().filter(x=>x.a.score>=60).slice(0,3);return `<section class="small-section"><div class="section-heading"><div><h2>On the research radar</h2><p>Technical candidates from your available data. Start here, investigate further.</p></div><button class="text-link" data-nav="opportunities">Explore ${ico('arrow')}</button></div><div class="opportunity-grid">${rows.map(({h,a})=>`<article class="opportunity-card" data-open-research="${esc(key(h))}"><div class="stock-identity">${logo(h)}<div><div class="stock-name">${esc(h.symbol)}</div><div class="stock-meta">${esc(h.sector||'Your watchlist')}</div></div><span class="mini-badge" style="margin-left:auto">+${a.score}</span></div><p>Price ${a.indicators.close>a.indicators.sma20?'above':'below'} its 20-session average. Volume at ${num(a.indicators.volumeRatio,2)}× its previous 20-bar baseline.</p><div class="opportunity-meta"><span>${state.source==='demo'?'SYNTHETIC · RESEARCH ONLY':'TECHNICAL RESEARCH'}</span><button class="text-link" data-open-research="${esc(key(h))}" aria-label="View ${esc(h.symbol)} evidence">View evidence ${ico('arrow')}</button></div></article>`).join('')||'<div class="note-box" style="margin:0;grid-column:1/-1">No bullish candidates currently meet the +60 watchlist threshold. Import more price histories to expand your research universe.</div>'}</div></section>`;}
function renderOpportunities(){let rows=ranked();if(state.opFilter==='bullish')rows=rows.filter(x=>x.a.score>=60);if(state.opFilter==='volume')rows=rows.filter(x=>x.a.indicators.volumeRatio>=1.5);return `<div class="filter-row"><label for="op-filter">Show candidates</label><select id="op-filter"><option value="all" ${state.opFilter==='all'?'selected':''}>All available histories</option><option value="bullish" ${state.opFilter==='bullish'?'selected':''}>Bullish score ≥ +60</option><option value="volume" ${state.opFilter==='volume'?'selected':''}>Volume factor ≥ 1.5×</option></select><span class="refresh-note">Universe: ${visibleHoldings().length} tracked stocks · finite research universe</span><button class="btn btn-small" data-action="add-holding">${ico('plus')}Add research stock</button>${credentialFor(activeAccount())?'<button class="btn btn-primary" data-action="scan">Scan 12-stock NSE universe</button>':''}</div>${runtime.scanMessage?`<div class="note-box">${esc(runtime.scanMessage)}</div>`:''}<section class="card"><div class="card-head"><div><h2 class="card-title">Ranked by directional rule score</h2><p class="card-caption">A technical starting point, not a recommended purchase or a return forecast.</p></div>${sourcePill(state.source)}</div><div class="table-wrap"><table><thead><tr><th>Stock</th><th>Score</th><th>Technical view</th><th class="numeric">Volume factor</th><th class="numeric">RSI (14)</th><th>Data / eligibility</th><th></th></tr></thead><tbody>${rows.map(({h,a})=>`<tr data-open-research="${esc(key(h))}"><td><div class="table-company">${logo(h)}<div><button class="stock-name-button" data-open-research="${esc(key(h))}" aria-label="View ${esc(h.symbol)} evidence">${esc(h.symbol)}</button><small>${esc(h.name||'Imported holding')}</small></div></div></td><td>${a.score>0?'+':''}${a.score}</td><td>${esc(a.bias)}</td><td class="numeric">${num(a.indicators.volumeRatio,2)}×</td><td class="numeric">${num(a.indicators.rsi14)}</td><td><span class="mini-badge ${a.trade.allowed?'':'amber'}">${a.trade.allowed?'RULES PASSED':'RESEARCH ONLY'}</span><span class="cell-secondary">${esc(a.trade.gateReasons[0]||'Still requires your own review')}</span></td><td>${ico('arrow')}</td></tr>`).join('')||'<tr><td colspan="7"><div class="empty-state">No candidates match this filter. Import at least 20 daily bars per stock.</div></td></tr>'}</tbody></table></div></section><div class="note-box">This ranking covers only the symbols and histories in your selected workspace. It does not assess valuation, earnings, corporate actions, suitability, or your wider financial circumstances. The score is a deterministic rule score, not a probability.</div>`;}
function empty(i,title,copy,action,label){return `<div class="empty-state">${ico(i)}<strong>${title}</strong>${copy}${action?`<br><button class="btn btn-primary" data-action="${action}">${label}</button>`:''}</div>`;}

function renderConnections(){return `<section class="family-hero"><div><span class="eyebrow">MULTIPLE ACCOUNTS. ONE WORKSPACE.</span><h2>Connect each account separately.</h2><p>Add multiple Kite or Groww accounts, or bring any other broker’s holdings through CSV.</p></div><button class="btn" data-action="add-account">${ico('plus')}Add account</button></section>${renderAccounts()}<section class="card content-card small-section"><h2>Choose your data source</h2><div class="two-col">${['kite','groww'].map(b=>`<div><h3>${b==='kite'?'Zerodha Kite':'Groww'}</h3><p>Read-only holdings, quotes, price history and derivative lookup. Each demat account needs its own access token. Quote polling runs every 15 seconds while the relevant view is open.</p><button class="btn" data-connect="${b}">Add ${b==='kite'?'Kite':'Groww'} account</button> <a href="${b==='kite'?'https://kite.trade/':'https://groww.in/trade-api'}" target="_blank" rel="noreferrer">Official access & pricing ↗</a></div>`).join('')}</div><div class="note-box">The app is free. Broker live-data and historical-data access may require a paid subscription. CSV imports are the free alternative and stay labelled unverified.</div></section><section class="card content-card small-section"><h2>Import from another platform</h2><p>Create an account, choose its family member, then import its holdings. Required CSV columns: <code>symbol,quantity,average_price</code>. Optional: <code>exchange,token,last_price,price_as_of</code>. Import completed daily OHLCV separately for technical research.</p><button class="btn" data-action="import-holdings">Import holdings CSV</button> <button class="btn" data-action="template">Download template</button><h3>Saved on this browser</h3><p>Account aliases, family members, holdings and research notes are saved on this device. Tokens stay in memory only and are removed on refresh or disconnect. Family members do not receive shared access. API requests pass through your hosted server to the selected broker. No orders or withdrawals are supported.</p><button class="btn" data-action="export">Export selected holdings</button> <button class="btn btn-danger" data-action="reset">Reset local workspace</button></section>`;}

function renderFno(){const f=runtime.fno,under=state.holdings.find(h=>key(h)===f.underlying)||selected();if(under)f.underlying=key(under);const a=analyzeDerivative({candles:candlesFor(under),...(under?provenance(under):{}),underlyingSymbol:under?.symbol,contractCandles:f.candles,quote:f.quote||{},contract:f.contract?{...f.contract,type:f.contract.instrumentType}: {},accountSize:Number(state.settings.accountSize),riskPercent:Number(state.settings.riskPercent)});const connected=Object.keys(runtime.credentials);return `<section class="card content-card"><div class="section-heading"><div><h2 style="margin-bottom:5px">Build the case before the trade.</h2><p>Select a daily underlying, then verify a matching contract through your broker.</p></div><span class="signal-pill ${a.allowed?'':'wait'}">${a.allowed?'RULES PASSED · REVIEW':'DO NOT TRADE · GATES BLOCKED'}</span></div><div class="fno-controls"><div class="form-row"><label for="fno-underlying">Underlying · daily analysis</label><select id="fno-underlying">${visibleHoldings().map(h=>`<option value="${esc(key(h))}" ${under&&key(under)===key(h)?'selected':''}>${esc(h.symbol)} · ${esc(accountLabel(h))}</option>`).join('')}</select><small>Use the underlying stock’s daily candles. Option premium candles cannot replace them.</small></div><div class="form-row"><label for="fno-account">Account for contract verification</label><select id="fno-account"><option value="">Choose an account</option>${state.accounts.filter(a=>['kite','groww'].includes(a.broker)).map(a=>`<option value="${esc(a.id)}" ${f.accountId===a.id?'selected':''}>${esc(memberName(a.memberId)+' · '+a.label)} ${credentialFor(a)?'· connected':'· reconnect'}</option>`).join('')}</select><small>Contract metadata must be verified. Quotes must satisfy the engine’s freshness gate.</small></div></div><div class="form-row"><label for="contract-search">Find futures or options</label><div class="fno-search-row"><input id="contract-search" value="${esc(f.query)}" placeholder="e.g. RELIANCE or NIFTY" autocomplete="off"><button class="btn btn-primary" data-action="search-contract">${ico('search')}Search contracts</button></div></div>${f.results.length?`<div class="search-results">${f.results.slice(0,30).map((c,i)=>`<button class="search-result" data-contract="${i}">${esc(c.symbol)} <small>${esc(c.exchange)} · ${esc(c.instrumentType)} · expiry ${esc(c.expiry||'unavailable')} · lot ${esc(c.lotSize||'unavailable')} · underlying ${esc(c.underlyingSymbol||'unverified')}</small></button>`).join('')}</div>`:''}${f.contract?`<div class="connection-status"><span class="dot"></span>${esc(f.contract.symbol)} · lot ${esc(f.contract.lotSize)} · expires ${esc(f.contract.expiry)} <button class="text-link" style="margin-left:auto" data-action="refresh-fno">${ico('refresh')}Refresh</button></div>`:`<div class="note-box">${connected.length?'Search and select a broker-verified contract.':'Connect Kite or Groww to verify an actual contract. The free demo demonstrates daily stock analysis; it never issues a derivative trade signal.'}</div>`}${f.error?`<div class="modal-error">${esc(f.error)}</div>`:''}<div class="metric-grid"><div class="metric-box"><span>Underlying direction</span><strong style="font-size:16px">${esc(a.bias||'Needs data')}</strong></div><div class="metric-box"><span>Daily underlying volume factor</span><strong>${num(a.underlying?.indicators?.volumeRatio,2)}×</strong></div><div class="metric-box"><span>Contract bid / ask spread</span><strong>${a.spreadPercent==null?'—':num(a.spreadPercent,2)+'%'}</strong></div><div class="metric-box"><span>5-minute contract volume factor</span><strong>${num(a.intradayVolumeRatio??a.contractVolumeRatio,2)}${(a.intradayVolumeRatio??a.contractVolumeRatio)!=null?'×':''}</strong></div><div class="metric-box"><span>Open interest · current quote</span><strong>${num(f.quote?.oi,0)}</strong><small class="cell-secondary">5-minute change: ${num(a.intradayOiChange,0)}</small></div><div class="metric-box"><span>Eligible lots under risk budget</span><strong>${a.position?.lots||0}</strong></div></div><div class="form-grid"><div class="form-row"><label for="account-size">Research account size (₹)</label><input type="number" id="account-size" min="1" step="1000" value="${esc(state.settings.accountSize)}"></div><div class="form-row"><label for="risk-percent">Maximum modeled risk (%)</label><input type="number" id="risk-percent" min="0.01" max="2" step=".1" value="${esc(state.settings.riskPercent)}"></div></div><div class="two-col"><div><h3>Conditions that need attention</h3><ul class="blocker-list">${a.gateReasons.map(r=>`<li>${esc(r)}</li>`).join('')||'<li>Current mechanical gates pass. Review costs, margin, earnings and suitability before any decision.</li>'}</ul></div><div><h3>Conditional underlying scenario</h3><div class="analysis-details"><div class="analysis-line"><span>Trigger / entry reference</span><b>${money(a.underlying?.trade?.entry,2)}</b></div><div class="analysis-line"><span>Invalidation reference</span><b>${money(a.underlying?.trade?.stop,2)}</b></div><div class="analysis-line"><span>Scenario target</span><b>${money(a.underlying?.trade?.target,2)}</b></div><div class="analysis-line"><span>Risk budget</span><b>${money(a.position?.riskBudget)}</b></div><div class="analysis-line"><span>Modeled loss per lot</span><b>${money(a.position?.riskPerLot)}</b></div><div class="analysis-line"><span>Contract quote time</span><b>${dateTime(f.quote?.asOf||f.quote?.timestamp)}</b></div></div><p>${esc(a.position?.sizingBasis||'')}</p><p>${esc(a.note||'')}</p></div></div><div class="note-box">These are conditional research scenarios, never predictions of a certain move. A volume factor compares a completed bar with its previous 20 bars; it is not a forecast. Options can lose their entire premium. Greeks, implied volatility, event risk and time-of-day volume seasonality are not modeled. No trade execution is provided.</div></section>`;}

function renderMethodology(){return `<div class="two-col"><section class="card content-card"><h2>Evidence, in plain sight.</h2><p>StockLens is a transparent technical research workspace. It helps you inspect a holding, define a review horizon and see why a setup is blocked. It cannot reliably predict the market or determine a suitable investment for you.</p><h3>How the score works</h3><p>The directional score ranges from −100 to +100. Price versus SMA20 contributes ±25, SMA20 versus SMA50 ±20, price versus EMA20 ±20, RSI’s directional band ±15, and 10-session momentum ±20. Missing or neutral evidence contributes zero.</p><p>A score ≥ +60 adds a bullish research candidate. A score ≤ −60 indicates a bearish watchlist. Other scores suggest holding for review. These labels describe technical evidence, not an instruction to buy, sell or keep a stock.</p><h3>Volume increase factor</h3><p>Latest completed bar volume ÷ mean volume of the previous 20 completed bars. The evaluated bar is excluded from its baseline. A factor of 1.5× means 50% more volume than the baseline. Intraday bars are not adjusted for time-of-day seasonality.</p><h3>Holding time is a review interval</h3><p>Swing analysis prompts review in 5–15 trading sessions. The optional wider technical lens uses 20–60. Long-term analysis has a separate thesis, your own planned holding window, valuation inputs and a review date. Intraday / F&O applies daily bias plus 5-minute contract confirmation. Review sooner when the scenario invalidates, data deteriorates, earnings change the thesis or your own constraints change. This is not an estimated time to profit.</p><button class="btn" data-action="settings">${ico('settings')}Choose research horizon</button></section><section class="card content-card"><h2>Know what the rules leave out.</h2><h3>Conditional price scenarios</h3><p>Directional scenarios use the latest high or low with an ATR14 buffer. Swing mode uses 1.5× ATR risk and 3× ATR reward; position mode uses 2× and 4×. Structural stops can increase the risk distance. Gross reward/risk must remain at least 2:1.</p><h3>What blocks an eligible setup</h3><p>Synthetic or stale data, unconfirmed provenance, insufficient completed bars, weak direction, volume below 1.5×, invalid prices or inadequate reward/risk. CSV imports always remain unverified research data. Displayed scenario levels are not forecasts.</p><h3>Extra checks for F&O</h3><p>A recent quote, positive bid and ask, a spread no wider than 1%, positive volume and OI, matching underlying, verified lot size, valid expiry and an affordable full lot. Long-option sizing reserves the full ask premium as possible loss. Futures require separate broker margin checks. Expiry-day trades are blocked.</p><h3>Outside the model</h3><p>Valuation, fundamentals, earnings events, corporate actions, suitability, taxes, brokerage, liquidity gaps, slippage, IV and Greeks are not modeled. Imported and broker candles may not be adjusted for corporate actions. Historical patterns can fail.</p><h3>Official data documentation</h3><p><a href="https://kite.trade/docs/connect/v3/" target="_blank" rel="noreferrer">Kite Connect API ↗</a><br><a href="https://groww.in/trade-api/docs" target="_blank" rel="noreferrer">Groww Trading API ↗</a><br><a href="https://kite.trade/" target="_blank" rel="noreferrer">Kite plans and pricing ↗</a><br><a href="https://groww.in/trade-api" target="_blank" rel="noreferrer">Groww plans and pricing ↗</a></p></section></div>`;}

function openModal(title,content,actions='',wide=false){if(!$('.modal'))runtime.modalReturnFocus=document.activeElement;toggleMenu(false,false);$('#app').inert=true;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section role="dialog" aria-modal="true" aria-labelledby="modal-title" class="modal ${wide?'wide':''}"><div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${ico('close')}</button></div>${content}${actions?`<div class="modal-actions">${actions}</div>`:''}</section></div>`;setTimeout(()=>($('.modal input')||$('.modal button'))?.focus(),30);}
function closeModal(){const wasOpen=Boolean($('.modal'));$('#modal-root').innerHTML='';$('#app').inert=false;if(wasOpen){const target=runtime.modalReturnFocus;const fallback=$('.nav button.active');(target?.isConnected?target:fallback)?.focus?.();}runtime.modalReturnFocus=null;}
function toggleMenu(open,restoreFocus=true){const sidebar=$('.sidebar');if(!sidebar)return;sidebar.classList.toggle('open',open);const backdrop=$('.nav-backdrop');if(backdrop)backdrop.hidden=!open;const trigger=$('[data-action="menu"]');trigger?.setAttribute('aria-expanded',String(open));if(open)$('.sidebar-close')?.focus();else if(restoreFocus)trigger?.focus();}
function containFocus(event,container){const items=[...container.querySelectorAll('a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex="0"]')].filter(el=>el.getClientRects().length);if(!items.length)return;const first=items[0],last=items.at(-1);if(event.shiftKey&&(document.activeElement===first||!container.contains(document.activeElement))){event.preventDefault();last.focus();}else if(!event.shiftKey&&(document.activeElement===last||!container.contains(document.activeElement))){event.preventDefault();first.focus();}}



function holdingModal(id){const h=state.holdings.find(x=>key(x)===id);openModal(h?'Edit holding':'Add a tracked stock',`<p>${h?'Update the quantity and average cost of this holding.':'Enter a stock from any platform. Set quantity to 0 for a research-only watchlist entry. Add its history after saving.'}</p><form id="holding-form" data-id="${esc(id||'')}"><div class="form-row"><label for="holding-account">Demat account</label><select id="holding-account" name="accountId" ${h?'disabled':''}>${accountOptions(h?.accountId||activeAccount()?.id)}</select></div><div class="form-grid"><div class="form-row"><label for="holding-symbol">Symbol</label><input id="holding-symbol" name="symbol" value="${esc(h?.symbol||'')}" placeholder="RELIANCE" maxlength="50" required ${h?'readonly':''}></div><div class="form-row"><label for="holding-exchange">Exchange</label><select id="holding-exchange" name="exchange"><option ${h?.exchange!=='BSE'?'selected':''}>NSE</option><option ${h?.exchange==='BSE'?'selected':''}>BSE</option></select></div><div class="form-row"><label for="holding-quantity">Quantity</label><input id="holding-quantity" name="quantity" type="number" min="0" step="any" value="${esc(h?.quantity??0)}" required></div><div class="form-row"><label for="holding-average">Average price (₹)</label><input id="holding-average" name="average_price" type="number" min="0" step="any" value="${esc(h?.average_price??0)}" required></div></div><div class="form-row"><label for="holding-token">Instrument token (optional)</label><input id="holding-token" name="token" value="${esc(h?.token||'')}" placeholder="Needed only for some broker lookups"></div><div class="modal-actions">${h?`<button type="button" class="btn btn-danger" style="margin-right:auto" data-remove="${esc(id)}">${ico('trash')}Remove</button>`:''}<button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn btn-primary" type="submit">Save holding</button></div></form>`);}
function settingsModal(){openModal('Your research preferences',`<p>Choose a review cadence and a conservative modeled risk budget. These do not establish investment suitability.</p><form id="settings-form"><div class="form-row"><label for="research-horizon">Research horizon</label><select id="research-horizon" name="horizon"><option value="swing" ${state.settings.horizon==='swing'?'selected':''}>Swing · review in 5–15 trading sessions</option><option value="position" ${state.settings.horizon==='position'?'selected':''}>Position · review in 20–60 trading sessions</option></select></div><div class="form-grid"><div class="form-row"><label for="settings-account">Account size (₹)</label><input id="settings-account" type="number" min="1" name="accountSize" value="${esc(state.settings.accountSize)}" required></div><div class="form-row"><label for="settings-risk">Modeled risk per setup (%)</label><input id="settings-risk" type="number" min="0.01" max="2" step=".01" name="riskPercent" value="${esc(state.settings.riskPercent)}" required></div></div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn btn-primary" type="submit">Save preferences</button></div></form>`);}
function detailsModal(){const h=selected();if(!h)return;const a=analysis(h);openModal(`${esc(h.symbol)} · behind the assessment`,`<p>${esc(a.reviewHorizon)} All levels are conditional scenarios, not predictions.</p><div class="tag-list">${sourcePill(h.source)}<span class="tag">Score ${a.score>0?'+':''}${a.score} / ±100</span><span class="tag">${a.barCount} completed bars</span></div><h3 style="font-size:12px;margin-top:22px">Score contributions</h3><div class="analysis-details">${a.scoreBreakdown.map(r=>`<div class="analysis-line"><span>${esc(r.rule)}</span><b>${r.points>0?'+':''}${r.points}</b></div>`).join('')}</div><h3 style="font-size:12px;margin-top:22px">Conditional levels</h3><div class="analysis-details"><div class="analysis-line"><span>Entry reference</span><b>${money(a.trade.entry,2)}</b></div><div class="analysis-line"><span>Invalidation</span><b>${money(a.trade.stop,2)}</b></div><div class="analysis-line"><span>Scenario target</span><b>${money(a.trade.target,2)}</b></div><div class="analysis-line"><span>Gross reward / risk</span><b>${num(a.trade.riskReward,2)} : 1</b></div></div><h3 style="font-size:12px;margin-top:22px">Eligibility conditions</h3><ul class="blocker-list">${a.trade.gateReasons.map(r=>`<li>${esc(r)}</li>`).join('')||'<li>Mechanical rules passed. Human research is still required.</li>'}</ul><p style="margin-top:15px;margin-bottom:0">${esc(a.trade.levelBasis||'')} ${esc(a.warnings.join(' '))}</p>`,`<button class="btn btn-primary" data-action="close-modal">Done</button>`,true);}

async function api(id,action,payload={}){if(location.protocol==='file:')throw new Error('Broker connections need the hosted app or local server. CSV analysis works in this offline file.');const a=accountById(id),credentials=runtime.credentials[id];if(!a||!['kite','groww'].includes(a.broker)||!credentials)throw new Error('Connect the selected demat account first.');const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),25000);try{const r=await fetch('/api/broker',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({broker:a.broker,action,credentials,...payload}),signal:controller.signal});const data=await r.json();if(!r.ok||data.error)throw new Error(typeof data.error==='string'?data.error:data.error?.message||data.message||'Broker request failed.');return data;}catch(e){if(e.name==='AbortError')throw new Error('Broker request timed out. Try again.');throw e;}finally{clearTimeout(timer);}}

async function connectForm(form){const id=form.dataset.account,a=accountById(id),button=form.querySelector('[type=submit]');if(!a)return;const b=a.broker,fd=new FormData(form),creds={accessToken:String(fd.get('accessToken')||'').trim(),...(b==='kite'?{apiKey:String(fd.get('apiKey')||'').trim()}:{})};if(Object.entries(runtime.credentials).some(([other,c])=>other!==id&&accountById(other)?.broker===b&&c.accessToken===creds.accessToken)){toast('This token is already connected to another account. Use that account to avoid counting it twice.',true);return;}button.disabled=true;button.textContent='Connecting…';const previous=runtime.credentials[id];runtime.credentials[id]=creds;if(runtime.fno.accountId===id)resetFnoEvidence();const epoch=(runtime.connectionEpoch[id]||0)+1;runtime.connectionEpoch[id]=epoch;try{const data=await api(id,'holdings');if(!accountById(id)||runtime.connectionEpoch[id]!==epoch)return;if(!Array.isArray(data.holdings))throw Error('Broker did not return a verified holdings list. Existing holdings were preserved.');const incoming=data.holdings.map(h=>({...h,accountId:id,source:b,name:sampleNames[h.symbol]?.name||h.symbol})).filter(h=>h.quantity>0);state.holdings=replaceAccountHoldings(state.holdings,id,incoming);clearAccountCache(id);for(const k of Object.keys(state.imported))if(k.startsWith(id+':'))delete state.imported[k];a.lastSync=new Date().toISOString();a.dataMode='broker';setScope('account:'+id,false);resetFnoEvidence();runtime.fno.accountId=id;runtime.fno.broker=b;runtime.lastFetch=a.lastSync;persist();closeModal();render();toast(`Connected ${a.label}. Imported ${incoming.length} holdings.`);await refreshMarket(true);}catch(e){if(runtime.connectionEpoch[id]!==epoch)return;if(previous)runtime.credentials[id]=previous;else delete runtime.credentials[id];const error=$('#connection-error');if(error)error.innerHTML=`<div class="modal-error">${esc(e.message)}</div>`;else toast(e.message,true);button.disabled=false;button.textContent='Connect & import holdings';}}

async function refreshMarket(show=false){if(runtime.busy)return;const scoped=visibleHoldings(),ids=[...new Set(scoped.map(h=>h.accountId||'legacy:'+h.source))].filter(id=>runtime.credentials[id]);if(!ids.length){if(show)toast('Connect an account in this view to refresh. Tokens are not saved.',true);return;}runtime.busy=true;const errors=[];try{for(const id of ids){const a=accountById(id),epoch=runtime.connectionEpoch[id]||0,hs=scoped.filter(h=>(h.accountId||'legacy:'+h.source)===id&&['NSE','BSE'].includes(h.exchange));try{for(let i=0;i<hs.length;i+=50){const batch=hs.slice(i,i+50),q=await api(id,'quotes',{symbols:batch.map(h=>({symbol:h.symbol,exchange:h.exchange}))});if(!credentialFor(id)||(runtime.connectionEpoch[id]||0)!==epoch)break;for(const h of batch){const value=q.quotes?.[`${h.exchange}:${h.symbol}`]||q.quotes?.[h.symbol];if(value)runtime.quotes[key(h)]={...value,price:value.price??value.lastPrice};else delete runtime.quotes[key(h)];}if(i+50<hs.length)await new Promise(r=>setTimeout(r,1100));}if(credentialFor(id)&&(runtime.connectionEpoch[id]||0)===epoch)runtime.lastFetch=new Date().toISOString();}catch(e){for(const [k,q]of Object.entries(runtime.quotes))if(k.startsWith(id+':'))q.isStale=true;errors.push(a.label+': '+e.message);}}const h=selected();if(h&&credentialFor(h)&&(!runtime.brokerCandles[key(h)]||show))try{await loadCandles(h);}catch(e){errors.push(e.message);}if(!['longterm','research'].includes(state.tab)&&!$('.modal'))render();if(show)toast(errors.length?errors.join(' · '):'Connected accounts refreshed. Check each price timestamp.',errors.length>0);}finally{runtime.busy=false;}}

async function scanUniverse(){const a=activeAccount();if(!a||!credentialFor(a)){toast('Select one connected account before scanning.',true);return;}if(runtime.busy){toast('A data request is already running.');return;}const id=a.id,epoch=runtime.connectionEpoch[id]||0,universe=['RELIANCE','TCS','HDFCBANK','INFY','BHARTIARTL','ITC','ICICIBANK','SBIN','LT','HINDUNILVR','MARUTI','TITAN'];runtime.busy=true;let loaded=0,failures=[];try{for(let i=0;i<universe.length;i++){if(!accountById(id)||!credentialFor(id)||(runtime.connectionEpoch[id]||0)!==epoch)break;const symbol=universe[i];runtime.scanMessage=`Checking ${i+1} / ${universe.length}: ${symbol}. Completed daily history, not a full-market scan.`;if(state.tab==='opportunities')render();let h=state.holdings.find(x=>x.accountId===id&&x.exchange==='NSE'&&x.symbol===symbol);if(!h){h={accountId:id,symbol,exchange:'NSE',source:a.broker,quantity:0,average_price:0,name:sampleNames[symbol]?.name||symbol};state.holdings.push(h);}try{await loadCandles(h);loaded++;}catch(e){failures.push(`${symbol}: ${e.message}`);}await new Promise(r=>setTimeout(r,400));}persist();runtime.scanMessage=`Loaded ${loaded} of ${universe.length} histories for ${a.label}. ${failures.join(' · ')}`;}finally{runtime.busy=false;}if(state.tab==='opportunities')render();}

async function loadCandles(h){if(!h||!credentialFor(h))return;const id=h.accountId||'legacy:'+h.source,epoch=runtime.connectionEpoch[id]||0,to=new Date(),from=new Date();from.setUTCDate(to.getUTCDate()-175);const r=await api(id,'candles',{symbol:h.symbol,token:h.token,exchange:h.exchange,interval:'day',segment:'CASH',from:from.toISOString().slice(0,10),to:to.toISOString().slice(0,10)});if(!credentialFor(id)||(runtime.connectionEpoch[id]||0)!==epoch)return;runtime.brokerCandles[key(h)]={fetchedDay:new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'}),candles:r.candles||[],asOf:r.asOf||r.candles?.at(-1)?.time,isStale:r.isStale??false};}

function resetFnoEvidence(){const f=runtime.fno;f.epoch=(f.epoch||0)+1;f.results=[];f.contract=null;f.quote=null;f.candles=[];f.lastHistory=0;f.error=null;}

async function searchContracts(){const f=runtime.fno;f.query=$('#contract-search')?.value.trim()||f.query;if(!f.query){toast('Enter a stock or index name.',true);return;}if(!credentialFor(f.accountId)){toast('Select and connect an account for contract verification.',true);return;}const id=f.accountId,epoch=f.epoch||0,connectionEpoch=runtime.connectionEpoch[id]||0;const current=()=>f.accountId===id&&(f.epoch||0)===epoch&&(runtime.connectionEpoch[id]||0)===connectionEpoch&&Boolean(credentialFor(id));const button=$('[data-action="search-contract"]');button.disabled=true;button.textContent='Searching…';try{const r=await api(id,'search',{query:f.query,symbol:f.query,segment:'FNO'});if(!current())return;f.results=(r.instruments||[]).filter(c=>['FUT','CE','PE'].includes(c.instrumentType));f.error=f.results.length?null:'No verified derivative contracts matched.';}catch(e){if(current())f.error=e.message;}render();}

async function refreshFno(history=false){const f=runtime.fno,c=f.contract,id=f.accountId,epoch=f.epoch||0,connectionEpoch=runtime.connectionEpoch[id]||0;if(!c||f.busy||!credentialFor(id))return;f.busy=true;const current=()=>f.contract===c&&f.accountId===id&&(f.epoch||0)===epoch&&(runtime.connectionEpoch[id]||0)===connectionEpoch&&Boolean(credentialFor(id));try{const r=await api(id,'quotes',{symbols:[{symbol:c.symbol,exchange:c.exchange}],segment:'FNO'});if(!current())return;const q=r.quotes?.[`${c.exchange}:${c.symbol}`]||r.quotes?.[c.symbol];f.quote=q?{...q,asOf:q.asOf||q.timestamp}:null;if(history||Date.now()-f.lastHistory>5*60000){const to=new Date(),from=new Date(Date.now()-6*86400000);const d=await api(id,'candles',{symbol:c.symbol,token:c.token,exchange:c.exchange,segment:'FNO',interval:'5minute',from:from.toISOString(),to:to.toISOString()});if(!current())return;f.candles=d.candles||[];f.lastHistory=Date.now();}const under=state.holdings.find(h=>key(h)===f.underlying);if(under&&!candlesFor(under).length)await loadCandles(under);if(!current())return;f.error=null;runtime.lastFetch=new Date().toISOString();}catch(e){if(current()){f.error=e.message;f.quote=null;}}finally{f.busy=false;}if(state.tab==='fno'&&current())render();}

function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;const s=text.replace(/^\uFEFF/,'');for(let i=0;i<s.length;i++){const c=s[i];if(c==='"'){if(quoted&&s[i+1]==='"'){cell+='"';i++;}else if(!quoted&&cell.trim()!=='')throw new Error('Invalid quote in CSV.');else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell.trim());cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&s[i+1]==='\n')i++;row.push(cell.trim());if(row.some(Boolean))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw new Error('CSV has an unclosed quote.');row.push(cell.trim());if(row.some(Boolean))rows.push(row);if(rows.length<2)throw new Error('CSV must contain a header and at least one data row.');const headers=rows.shift().map(x=>x.toLowerCase().replace(/\s+/g,'_'));if(new Set(headers).size!==headers.length)throw new Error('CSV headers must be unique.');return {headers,rows:rows.map((r,i)=>{if(r.length!==headers.length)throw new Error(`Row ${i+2} has ${r.length} columns; expected ${headers.length}.`);return Object.fromEntries(headers.map((h,j)=>[h,r[j]]));})};}
function download(filename,text){const blob=new Blob([text],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csvCell(v){const s=String(v??'');return /[",\n\r]/.test(s)?'"'+s.replaceAll('"','""')+'"':s;}
function exportHoldings(){const fields=['account_id','account','member','symbol','quantity','average_price','exchange','token','last_price','price_as_of'];download('stocklens-holdings.csv',fields.join(',')+'\n'+visibleHoldings().map(h=>{const a=accountById(h.accountId),q=quoteFor(h);return [h.accountId,a?.label,memberName(a?.memberId),h.symbol,h.quantity,h.average_price,h.exchange,h.token,q.price,q.timestamp].map(csvCell).join(',');}).join('\n'));}


function importCandlesPrompt(){const h=selected();if(!h){toast('Add or select a holding first.',true);return;}if(h.source==='demo'){openModal('Import real data for this symbol',`<p>To keep sample and imported data separate, ${esc(h.symbol)} will be added to the CSV workspace as an unowned watchlist stock. Enter your actual quantity and average cost separately. Your synthetic sample remains available.</p><div class="modal-info">Upload completed daily candles with columns <code>time,open,high,low,close,volume</code> and optional <code>oi</code>. Use ISO dates, one row per trading day. Only completed daily bars should be included.</div>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="choose-candles">Choose CSV</button>`);}else openModal('Import daily price history',`<p>Import daily OHLCV for <strong>${esc(h.symbol)}</strong>. At least 20 bars are required for indicators and 60 for setup rules.</p><div class="modal-info">Required columns: <code>time,open,high,low,close,volume</code>. Optional: <code>oi</code>. Use unique ISO dates and completed daily bars. CSV source and freshness cannot be independently verified.</div>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="choose-candles">Choose CSV</button>`);}

function accountById(id){return state.accounts.find(a=>a.id===id);}
function activeAccount(){return state.scope?.startsWith('account:')?accountById(state.scope.slice(8)):null;}
function memberName(id){return state.members.find(m=>m.id===id)?.name||'You';}
function accountLabel(h){const a=accountById(h.accountId||'legacy:'+(h.source||'csv'));return a?`${memberName(a.memberId)} · ${a.label}`:sourceLabel(h.source);}
function credentialFor(value){const id=typeof value==='string'?value:value?.accountId||value?.id||'legacy:'+value?.source;return runtime.credentials[id];}
function scopeLabel(){const a=activeAccount();return a?`${memberName(a.memberId)} · ${a.label}`:state.scope?.startsWith('member:')?memberName(state.scope.slice(7))+' · all accounts':'All family accounts';}
function setScope(scope,save=true){state.scope=scope;state.source=activeAccount()?.broker||'combined';state.selected=null;if(save){persist();render();}}
function accountOptions(id,includeDemo=false){return state.accounts.filter(a=>includeDemo||a.broker!=='demo').map(a=>`<option value="${esc(a.id)}" ${id===a.id?'selected':''}>${esc(memberName(a.memberId)+' · '+a.label)}</option>`).join('');}
function scopeBar(){return `<div class="scope-bar"><div class="form-row"><label for="scope-select">Portfolio view</label><select id="scope-select"><option value="all" ${state.scope==='all'?'selected':''}>All family accounts</option><optgroup label="Family members">${state.members.map(m=>`<option value="member:${esc(m.id)}" ${state.scope==='member:'+m.id?'selected':''}>${esc(m.name)} · all accounts</option>`).join('')}</optgroup><optgroup label="Individual accounts">${state.accounts.map(a=>`<option value="account:${esc(a.id)}" ${state.scope==='account:'+a.id?'selected':''}>${esc(a.broker==='demo'?'Synthetic sample':memberName(a.memberId)+' · '+a.label)}</option>`).join('')}</optgroup></select></div><span class="scope-help">${state.source==='demo'?'Sample data stays separate from family totals.':'Totals include only accounts and holdings added here.'}</span><button class="btn btn-small" data-action="add-account">${ico('plus')}Add account</button><button class="text-link" data-action="refresh">${ico('refresh')}Refresh connected</button></div>`;}
function ensureCsvAccount(){let a=state.accounts.find(a=>a.broker==='csv'&&a.memberId==='self');if(!a){a={id:newId('account'),label:'My CSV account',broker:'csv',memberId:'self'};state.accounts.push(a);}return a;}
function newId(prefix){return prefix+'-'+(globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2));}
function accountModal(id=null,broker='csv'){const a=accountById(id);openModal(a?'Edit account':'Add a demat account',`<p>Use a memorable alias. Add separate accounts for yourself or family members who have authorised you to review their holdings.</p><form id="account-form" data-id="${esc(id||'')}"><div class="form-row"><label for="account-label">Account name</label><input id="account-label" name="label" required maxlength="60" placeholder="e.g. My Kite or Mum’s investments" value="${esc(a?.label||'')}"></div><div class="form-grid"><div class="form-row"><label for="account-broker">Platform</label><select id="account-broker" name="broker" ${a?'disabled':''}>${[['kite','Zerodha Kite'],['groww','Groww'],['csv','Other platform / CSV']].map(([v,l])=>`<option value="${v}" ${(a?.broker||broker)===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="form-row"><label for="account-member">Family member</label><select id="account-member" name="memberId">${state.members.map(m=>`<option value="${esc(m.id)}" ${(a?.memberId||'self')===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}<option value="new">+ Add family member</option></select></div></div><div class="form-row"><label for="new-member">New family member name (if selected above)</label><input id="new-member" name="memberName" maxlength="60" placeholder="e.g. Mum"></div><div class="modal-info">Family views combine data on this browser. They do not create shared logins or grant access to another person’s demat account. Avoid adding the same real account twice.</div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button type="submit" class="btn btn-primary">${a?'Save account':'Add account'}</button></div></form>`);}
function importHoldingsModal(id){if(!state.accounts.some(a=>a.broker!=='demo')){accountModal();return;}openModal('Import an account snapshot',`<p>Choose the destination account. This replaces that account’s holdings only; all other accounts stay intact.</p><form id="import-account-form"><div class="form-row"><label for="import-account">Destination account</label><select name="accountId" id="import-account">${accountOptions(id||activeAccount()?.id)}</select></div><p>Required: <code>symbol,quantity,average_price</code>. Optional: <code>exchange,token,last_price,price_as_of</code>. A snapshot price needs its ISO timestamp and remains labelled unverified. Empty snapshots must come from a successful broker sync.</p><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn btn-primary">Choose CSV</button></div></form>`);}
async function importHoldingsFile(t){try{const id=runtime.holdingsImportAccount;const account=accountById(id);if(!account||account.broker==='demo')throw Error('Choose a destination account before importing.');if(t.files[0].size>5*1024*1024)throw Error('Please use a holdings CSV smaller than 5 MB.');const parsed=parseCSV(await t.files[0].text());for(const k of ['symbol','quantity','average_price'])if(!parsed.headers.includes(k))throw Error(`Missing required column: ${k}`);const incoming=parsed.rows.map((r,i)=>{const symbol=r.symbol.toUpperCase().trim(),quantity=Number(r.quantity),average_price=Number(r.average_price),exchange=(r.exchange||'NSE').toUpperCase();let lastPrice,priceAsOf;if(r.last_price?.trim()){lastPrice=Number(r.last_price);priceAsOf=r.price_as_of?.trim();if(!(lastPrice>0)||!Number.isFinite(lastPrice)||!priceAsOf||!/^\d{4}-\d{2}-\d{2}T/.test(priceAsOf)||!/(?:Z|[+-]\d{2}:\d{2})$/.test(priceAsOf)||!Number.isFinite(Date.parse(priceAsOf))||Date.parse(priceAsOf)>Date.now())throw Error(`Row ${i+2}: last_price needs a positive price and a past ISO price_as_of with timezone.`);}if(!(quantity>0)||!(average_price>0))throw Error(`Invalid quantity or average price on row ${i+2}.`);if(r.account_id&&r.account_id!==id)throw Error('This export contains another account. Import one account at a time.');return {accountId:id,symbol,quantity,average_price,exchange,token:r.token||undefined,name:sampleNames[symbol]?.name||symbol,source:'csv',lastPrice,priceAsOf};});state.holdings=replaceAccountHoldings(state.holdings,id,incoming);clearAccountCache(id);account.lastSync=new Date().toISOString();account.dataMode='csv';setScope('account:'+id,false);state.tab='portfolio';persist();render();toast(`Imported ${incoming.length} holdings into ${account.label}. Snapshot prices remain unverified.`);}catch(e){toast(e.message,true);}finally{t.value='';runtime.holdingsImportAccount=null;}}
function clearAccountCache(id){for(const field of ['quotes','brokerCandles'])for(const k of Object.keys(runtime[field]))if(k.startsWith(id+':'))delete runtime[field][k];}
function disconnectAccount(id){delete runtime.credentials[id];runtime.connectionEpoch[id]=(runtime.connectionEpoch[id]||0)+1;clearAccountCache(id);if(runtime.fno.accountId===id){runtime.fno.epoch=(runtime.fno.epoch||0)+1;runtime.fno.results=[];runtime.fno.contract=null;runtime.fno.quote=null;runtime.fno.candles=[];}render();}
function connectionModal(id){const a=accountById(id);if(!a){accountModal(null,['kite','groww'].includes(id)?id:'kite');return;}const b=a.broker;openModal('Connect '+esc(a.label),`<p>${esc(memberName(a.memberId))} · ${esc(sourceLabel(b))}. This connection updates only this account.</p><div class="modal-info">Use the matching account’s existing access token. Tokens stay in memory and are sent through this app’s server to the broker. Never enter passwords, PINs, OTPs or API secrets. Market data may require a paid broker subscription.</div><form id="connect-form" data-account="${esc(a.id)}" data-broker="${esc(b)}">${b==='kite'?'<div class="form-row"><label for="api-key">API key</label><input id="api-key" name="apiKey" autocomplete="off" required></div>':''}<div class="form-row"><label for="access-token">Access token</label><input id="access-token" name="accessToken" type="password" autocomplete="off" required></div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button type="submit" class="btn btn-primary">Connect & import holdings</button></div><div id="connection-error" role="alert"></div></form>`);}
function chooseBrokerModal(){accountModal(null,'kite');}
function renderAccounts(){const accounts=state.accounts.filter(a=>a.broker!=='demo');return `<div class="family-grid">${accounts.map(a=>{const t=aggregatePortfolio(scopeHoldings(state.holdings,state.accounts,'account:'+a.id),quoteFor,state.accounts,state.members);return `<article class="card account-card"><div class="account-top"><span class="broker-icon ${esc(a.broker)}">${esc(a.broker==='kite'?'K':a.broker==='groww'?'G':'C')}</span><div><h3>${esc(a.label)}</h3><span class="account-meta">${esc(memberName(a.memberId))} · ${esc(sourceLabel(a.broker))}</span></div></div><div class="account-value">${money(t.currentValue)}<small>${t.isPartial?'Partial value':t.pricedCount?'Priced holdings':'Awaiting prices'}</small></div><p class="account-meta">${t.ownedCount} holdings · Cost ${money(t.invested)}<br>${a.lastSync?'Holdings imported '+dateTime(a.lastSync):'Holdings not imported yet'}<br>${credentialFor(a)?'Connected this session':a.broker==='csv'?'CSV snapshot account':'Disconnected · reconnect to refresh'}</p><div class="account-actions"><button class="btn btn-small" data-account-view="${esc(a.id)}">View</button>${['kite','groww'].includes(a.broker)?`<button class="btn btn-small" data-connect-account="${esc(a.id)}">${credentialFor(a)?'Sync / reconnect':'Connect'}</button>${credentialFor(a)?`<button class="text-link" data-disconnect-account="${esc(a.id)}">Disconnect</button>`:''}`:''}<button class="btn btn-small" data-import-account="${esc(a.id)}">Import CSV</button><button class="text-link" data-edit-account="${esc(a.id)}">Edit</button><button class="text-link" data-delete-account="${esc(a.id)}">Remove</button></div></article>`;}).join('')}<button class="card account-card family-add" data-action="add-account">${ico('plus')}<strong>Add another account</strong><span>Kite, Groww or any broker via CSV</span></button></div>`;}
function renderFamily(){const hs=visibleHoldings(),t=aggregatePortfolio(hs,quoteFor,state.accounts,state.members),pending=state.accounts.filter(a=>a.broker!=='demo'&&!a.lastSync).length;return `<section class="family-hero"><div><span class="eyebrow">${esc(scopeLabel())}</span><h2>See the whole picture.</h2><p>One place to review your accounts, family exposure and holdings that overlap.</p></div><button class="btn" data-action="add-account">${ico('plus')}Add demat account</button></section><div class="family-metrics">${[['Holdings value',money(t.currentValue),t.isPartial?'Partial · prices missing':t.pricedCount?'Based on available snapshots':'Add holdings and prices'],['Invested cost',money(t.invested),'Across included holdings'],['Unrealised P&L',t.pnl===null?'—':(t.pnl>=0?'+':'−')+money(Math.abs(t.pnl)),'Priced positions only'],['Accounts / members with holdings',t.accountCount+' / '+t.memberCount,t.stockCount+' unique exchange-listed stocks']].map(([l,v,n])=>`<article class="card family-metric"><span>${l}</span><strong>${v}</strong><small>${n}</small></article>`).join('')}</div><div class="coverage-strip"><span>${t.pricedCount}/${t.ownedCount} positions priced</span><span>${t.missingCount} missing prices</span><span>${t.staleCount} stale or unverified</span><span>${pending} accounts without an import timestamp</span></div><p class="scope-help">This is a holdings view, not total net worth. Cash, liabilities and accounts not added here are excluded. Prices may have different timestamps. Family totals exclude synthetic sample data.</p><div class="section-heading"><h2>Your demat accounts</h2><button class="text-link" data-action="export">Export selected holdings ${ico('download')}</button></div>${renderAccounts()}<div class="family-split small-section"><section class="card content-card"><h2>Concentration & overlap</h2><p>Weights use available priced holdings only${t.isPartial?' and are incomplete':''}. Identical symbols on different exchanges remain separate.</p>${t.stocks.filter(s=>s.quantity>0).slice(0,8).map(s=>`<div class="allocation-row"><div><strong>${esc(s.symbol)}</strong><small>${esc(s.exchange)} · ${s.accountCount} account${s.accountCount===1?'':'s'}</small></div><b>${num(s.weightPercent,1)}%</b><div class="allocation-track"><span style="width:${Math.max(0,Math.min(100,s.weightPercent||0))}%"></span></div></div>`).join('')||'<p class="family-empty">Add holdings to see exposure across your family.</p>'}<div class="note-box">${t.overlaps.length?`${t.overlaps.length} stocks appear in more than one account. Multiple accounts do not automatically mean diversified investments.`:'No overlapping owned stocks in the included data.'}</div></section><section class="card content-card"><h2>By family member</h2>${t.memberBreakdown.map(m=>`<div class="family-member-row"><div><strong>${esc(m.name)}</strong><small>${m.accountCount} accounts · ${m.ownedCount} holdings</small></div><div><strong>${money(m.currentValue)}</strong><small>${m.isPartial?'Partial value':m.staleCount?'Snapshot prices':'Available quote value'}</small></div></div>`).join('')||'<p class="family-empty">Create an account and assign its owner to begin.</p>'}<p>Family accounts stay separate for connections, costs and position sizing. This view is local to this browser and does not share credentials or records with other family members.</p><button class="btn" data-nav="research">${ico('shield')}Review risk & allocation</button></section></div><section class="card content-card small-section"><h2>Combined stock positions</h2><div class="table-wrap"><table><thead><tr><th>Stock</th><th>Accounts</th><th class="numeric">Shares</th><th class="numeric">Weighted cost</th><th class="numeric">Value</th><th class="numeric">P&L</th><th>Coverage</th></tr></thead><tbody>${t.stocks.map(s=>`<tr><td>${esc(s.symbol)}<small class="cell-secondary">${esc(s.exchange)}</small></td><td>${s.accountCount}</td><td class="numeric">${num(s.quantity,4)}</td><td class="numeric">${money(s.averagePrice,2)}</td><td class="numeric">${money(s.currentValue)}</td><td class="numeric">${money(s.pnl)}</td><td>${s.pricedCount}/${s.ownedCount} priced${s.isPartial?' · partial':''}</td></tr>`).join('')||'<tr><td colspan="7">No holdings in this view.</td></tr>'}</tbody></table></div></section>`;}
function renderResearch(){const h=selected(),id=h?key(h):'none',saved=state.research[id]||{},check=evaluateChecklist(saved),plan=runtime.planResult,total=aggregatePortfolio(visibleHoldings(),quoteFor,state.accounts,state.members),targets=state.targets[state.scope]||[],drift=!total.isPartial&&total.pricedCount?analyzeDrift(total.stocks.filter(s=>s.currentValue>0).map(s=>({symbol:s.symbol,exchange:s.exchange,marketValue:s.currentValue})),targets):null;return `<div class="research-grid"><section class="card content-card research-form"><h2>Position size, within your limits</h2><p>Long cash equities in whole shares. Enter the selected account’s own equity and available cash, even in a family view.</p><form id="size-form"><div class="form-row"><label for="plan-account">Account for this plan</label><select id="plan-account" name="accountId" required><option value="">Choose one account</option>${accountOptions(runtime.planInput?.accountId||activeAccount()?.id)}</select></div><div class="form-row"><label for="plan-symbol">Stock symbol (NSE / BSE)</label><input id="plan-symbol" name="symbol" required maxlength="50" value="${esc(runtime.planInput?.symbol||h?.symbol||'')}" placeholder="RELIANCE"></div><div class="form-grid">${[['equity','Account equity (₹)'],['cashAvailable','Available cash (₹)'],['entry','Entry assumption (₹)'],['stop','Invalidation price (₹)'],['riskPercent','Risk limit (%)'],['maxPositionPercent','Stock allocation cap (%)']].map(([k,l])=>`<div class="form-row"><label for="size-${k}">${l}</label><input type="number" id="size-${k}" name="${k}" min="0" step="any" required value="${esc(runtime.planInput?.[k]??'')}"></div>`).join('')}</div><div class="form-row"><label for="size-existing">Existing value of this stock in this account (₹)</label><input type="number" id="size-existing" name="existingSymbolValue" min="0" step="any" required value="${esc(runtime.planInput?.existingSymbolValue??'')}" placeholder="0 if you do not own it"></div><button class="btn btn-primary">Calculate share limit</button></form>${plan?`<div class="research-result" role="status">${plan.valid?`<strong>${num(plan.shares,0)} shares within your inputs</strong><p>Position value ${money(plan.positionValue)} · modeled stop risk ${money(plan.plannedRisk)}<br>Binding limit: ${esc(plan.bindingConstraints.join(', '))}</p>`:`<strong>Review inputs</strong><p>${esc(plan.errors.join(' '))}</p>`}<small>${esc(plan.note)}</small></div>`:''}</section><section class="card content-card research-form"><h2>Before a trade: write the case</h2><p>${h?esc(h.symbol+' · '+accountLabel(h)):'Choose a stock from an account first.'} · records your review, not a forecast.</p>${h?`<form id="research-form" data-id="${esc(id)}"><div class="form-row"><label for="research-stock">Research holding</label><select id="research-stock">${visibleHoldings().map(x=>`<option value="${esc(key(x))}" ${key(x)===id?'selected':''}>${esc(x.symbol+' · '+accountLabel(x))}</option>`).join('')}</select></div>${[['thesis','Thesis & evidence'],['invalidation','What would invalidate it?'],['catalyst','Why review now?']].map(([k,l])=>`<div class="form-row"><label for="review-${k}">${l}</label><textarea id="review-${k}" name="${k}" rows="2" maxlength="3000">${esc(saved[k]||'')}</textarea></div>`).join('')}${[['eventChecked','I checked upcoming results and corporate events'],['liquidityChecked','I reviewed liquidity and execution costs'],['dataVerified','I verified the data source and timestamp']].map(([k,l])=>`<label class="checklist-row"><input type="checkbox" name="${k}" ${saved[k]===true?'checked':''}><span>${l}</span></label>`).join('')}<div class="form-row"><label for="review-date">Next review date</label><input id="review-date" type="date" name="reviewDate" value="${esc(saved.reviewDate||'')}"></div><button class="btn btn-primary">Save research review</button></form><div class="research-result"><strong>${check.complete?'Checklist complete':'Needs evidence'}</strong><p>${check.complete?'Your six review fields are complete.':check.missing.length+' review fields still need attention.'}${saved.savedAt?' Saved '+dateTime(saved.savedAt)+'.':''}</p><small>${esc(check.note)}</small></div>`:'<div class="family-empty">Add a holding, then record its evidence and review conditions.</div>'}</section></div><section class="card content-card small-section"><h2>Your allocation targets</h2><p>For ${esc(scopeLabel())}. Enter your own weights totaling 100%. Drift is measured in percentage points of included holdings value; cash is excluded.</p>${total.stocks.length?`<form id="targets-form" data-scope="${esc(state.scope)}"><div class="table-wrap"><table><thead><tr><th>Stock</th><th>Current weight</th><th>Your target %</th><th>Drift</th></tr></thead><tbody>${total.stocks.filter(s=>s.quantity>0).map((s,i)=>{const t=targets.find(t=>t.symbol===s.symbol&&t.exchange===s.exchange),d=drift?.rows?.find(r=>r.symbol===s.symbol&&r.exchange===s.exchange);return `<tr><td>${esc(s.symbol)} · ${esc(s.exchange)}</td><td>${num(s.weightPercent,1)}%${total.isPartial?' (partial)':''}</td><td><input aria-label="Target for ${esc(s.symbol)} ${esc(s.exchange)}" name="weight-${i}" type="number" step="any" min="0" max="100" required value="${esc(t?.weightPercent??'')}"></td><td>${d?num(d.driftPp,2)+' pp':'—'}</td></tr>`;}).join('')}</tbody></table></div><button class="btn" style="margin-top:16px">Save allocation targets</button></form><p class="scope-help">${total.isPartial?'Drift is blocked until every owned holding has a price.':total.hasStalePrices?'Comparison uses stale or unverified snapshot prices; refresh before decisions.':drift?.valid?'Targets saved. Positive drift means above your target.':'Save complete targets to calculate drift.'}</p>`:'<p>Add holdings to set your own allocation targets.</p>'}</section><div class="research-source-links">Methods adapted from <a href="https://github.com/Jakeschincariol/trader-skill" target="_blank" rel="noreferrer">trader-skill</a> and <a href="https://github.com/tradermonty/claude-trading-skills" target="_blank" rel="noreferrer">Claude Trading Skills</a>. Calculations run locally with transparent rules. <a href="/notices.txt" target="_blank">MIT attributions</a>.</div>`;}

document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.action==='add-account')accountModal();if(t.dataset.accountView){setScope('account:'+t.dataset.accountView,false);setTab('portfolio');persist();}if(t.dataset.connectAccount)connectionModal(t.dataset.connectAccount);if(t.dataset.disconnectAccount){disconnectAccount(t.dataset.disconnectAccount);toast('Account disconnected. Token removed from memory.');}if(t.dataset.importAccount)importHoldingsModal(t.dataset.importAccount);if(t.dataset.editAccount)accountModal(t.dataset.editAccount);if(t.dataset.deleteAccount){const a=accountById(t.dataset.deleteAccount);if(a)openModal('Remove '+esc(a.label)+'?',`<p>This removes this account’s holdings and research from this browser. The broker account is unchanged. Export the holdings first if needed.</p>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn btn-danger" data-confirm-delete-account="${esc(a.id)}">Remove local account</button>`);}if(t.dataset.confirmDeleteAccount){const id=t.dataset.confirmDeleteAccount;disconnectAccount(id);state.accounts=state.accounts.filter(a=>a.id!==id);state.holdings=state.holdings.filter(h=>h.accountId!==id);for(const store of [state.imported,state.theses,state.research])for(const k of Object.keys(store))if(k.startsWith(id+':'))delete store[k];delete state.targets['account:'+id];setScope('all',false);persist();closeModal();render();toast('Local account removed.');}});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='scope-select'){setScope(t.value);runtime.planResult=null;}if(t.id==='research-stock'){state.selected=t.value;render();}if(t.id==='fno-account'){runtime.fno.epoch=(runtime.fno.epoch||0)+1;runtime.fno.accountId=t.value;runtime.fno.broker=accountById(t.value)?.broker||'kite';runtime.fno.results=[];runtime.fno.contract=null;runtime.fno.quote=null;runtime.fno.candles=[];render();}});
document.addEventListener('submit',e=>{const form=e.target;if(!['account-form','import-account-form','research-form','size-form','targets-form'].includes(form.id))return;e.preventDefault();const fd=new FormData(form);try{
 if(form.id==='account-form'){const id=form.dataset.id,old=accountById(id),label=String(fd.get('label')||'').trim(),broker=old?.broker||String(fd.get('broker'));let memberId=String(fd.get('memberId'));if(!label||label.length>60||!['kite','groww','csv','manual'].includes(broker))throw Error('Enter an account name and supported platform.');if(memberId==='new'){const name=String(fd.get('memberName')||'').trim();if(!name||name.length>60)throw Error('Enter the new family member’s name.');const existing=state.members.find(m=>m.name.toLowerCase()===name.toLowerCase());if(existing)memberId=existing.id;else{memberId=newId('member');state.members.push({id:memberId,name});}}if(!state.members.some(m=>m.id===memberId))throw Error('Select a valid family member.');const a=old||{id:newId('account'),broker};Object.assign(a,{label,memberId});if(!old)state.accounts.push(a);setScope('account:'+a.id,false);state.tab='family';persist();closeModal();render();if(!old&&['kite','groww'].includes(broker))connectionModal(a.id);else toast(old?'Account updated.':'Account added. Import holdings when ready.');}
 if(form.id==='import-account-form'){const id=String(fd.get('accountId'));if(!accountById(id)||accountById(id).broker==='demo')throw Error('Select a real account.');runtime.holdingsImportAccount=id;closeModal();$('#holdings-file').click();}
 if(form.id==='research-form'){if(!state.holdings.some(h=>key(h)===form.dataset.id))throw Error('This holding is no longer available.');state.research[form.dataset.id]={thesis:String(fd.get('thesis')||'').trim(),invalidation:String(fd.get('invalidation')||'').trim(),catalyst:String(fd.get('catalyst')||'').trim(),eventChecked:fd.get('eventChecked')==='on',liquidityChecked:fd.get('liquidityChecked')==='on',dataVerified:fd.get('dataVerified')==='on',reviewDate:String(fd.get('reviewDate')||''),savedAt:new Date().toISOString()};persist();render();toast('Research review saved.');}
 if(form.id==='size-form'){const input=Object.fromEntries(fd),a=accountById(input.accountId);if(!a||a.broker==='demo')throw Error('Select a real account for position sizing.');input.symbol=String(input.symbol||'').trim().toUpperCase();if(!/^[A-Z0-9][A-Z0-9&_. -]{0,49}$/.test(input.symbol))throw Error('Enter a valid stock symbol.');for(const k of ['equity','cashAvailable','entry','stop','riskPercent','maxPositionPercent','existingSymbolValue'])input[k]=fd.get(k)===''?NaN:Number(fd.get(k));runtime.planInput=input;runtime.planResult=planPosition(input);render();}
 if(form.id==='targets-form'){if(form.dataset.scope!==state.scope)throw Error('Portfolio view changed; review targets again.');const t=aggregatePortfolio(visibleHoldings(),quoteFor,state.accounts,state.members),stocks=t.stocks.filter(s=>s.quantity>0);if(t.isPartial||!t.pricedCount)throw Error('Import a price for every owned holding before comparing targets.');const targets=stocks.map((s,i)=>({symbol:s.symbol,exchange:s.exchange,weightPercent:fd.get('weight-'+i)===''?NaN:Number(fd.get('weight-'+i))}));const d=analyzeDrift(stocks.map(s=>({symbol:s.symbol,exchange:s.exchange,marketValue:s.currentValue})),targets);if(!d.valid)throw Error(d.errors.join(' '));state.targets[state.scope]=targets;persist();render();toast('Allocation targets saved. Drift is in percentage points.');}
 }catch(error){toast(error.message,true);}});

document.addEventListener('click',async e=>{const t=e.target.closest('button,[data-select],[data-open-research]');if(!t)return;if(t.dataset.nav){closeModal();setTab(t.dataset.nav);return;}if(t.dataset.period){state.period=t.dataset.period;render();return;}if(t.dataset.connect){connectionModal(t.dataset.connect);return;}if(t.dataset.disconnect){const b=t.dataset.disconnect;delete runtime.credentials[b];for(const k of Object.keys(runtime.quotes))if(k.startsWith(b+':'))delete runtime.quotes[k];if(runtime.fno.broker===b){runtime.fno.epoch=(runtime.fno.epoch||0)+1;runtime.fno.results=[];runtime.fno.quote=null;runtime.fno.contract=null;runtime.fno.candles=[];}render();toast('Disconnected. Access token removed from memory.');return;}if(t.dataset.edit){holdingModal(t.dataset.edit);return;}if(t.dataset.remove){state.holdings=state.holdings.filter(h=>key(h)!==t.dataset.remove);delete state.imported[t.dataset.remove];persist();closeModal();render();toast('Holding removed from this workspace.');return;}if(t.dataset.openResearch){state.selected=t.dataset.openResearch;const h=selected();state.tab='overview';render();detailsModal();return;}if(t.dataset.select){state.selected=t.dataset.select;render();const h=selected();if(h&&credentialFor(h)&&!runtime.brokerCandles[key(h)]){try{await loadCandles(h);render();}catch(e){toast(e.message,true);}}return;}if(t.dataset.contract!==undefined){const f=runtime.fno;f.epoch=(f.epoch||0)+1;f.contract=f.results[Number(t.dataset.contract)];f.results=[];f.quote=null;f.candles=[];render();await refreshFno(true);return;}const act=t.dataset.action;if(act==='close-modal')closeModal();if(act==='menu')toggleMenu(true);if(act==='close-menu')toggleMenu(false);if(act==='connect')chooseBrokerModal();if(act==='add-holding'){if(!state.accounts.some(a=>a.broker!=='demo'))accountModal();else holdingModal();}if(act==='settings')settingsModal();if(act==='analysis-details')detailsModal();if(act==='export')exportHoldings();if(act==='refresh')await refreshMarket(true);if(act==='scan')await scanUniverse();if(act==='refresh-fno')await refreshFno(true);if(act==='search-contract')await searchContracts();if(act==='import-holdings')importHoldingsModal();if(act==='template')download('stocklens-holdings-template.csv','symbol,quantity,average_price,exchange,token,last_price,price_as_of\nRELIANCE,10,1400,NSE,,,\nTCS,5,3200,NSE,,,\n');if(act==='import-candles')importCandlesPrompt();if(act==='choose-candles'){runtime.importTarget=selected()?{...selected()}:null;closeModal();$('#candles-file').click();}if(act==='reset')openModal('Reset this browser workspace?','<p>This removes locally saved holdings, imported CSV histories and preferences, and disconnects broker tokens. Export anything you want to keep first.</p>','<button class="btn" data-action="close-modal">Cancel</button><button class="btn btn-danger" data-action="confirm-reset">Reset workspace</button>');if(act==='confirm-reset'){localStorage.removeItem('stocklens.v2');localStorage.removeItem('stocklens.v1');location.reload();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('.modal'))closeModal();else toggleMenu(false);}if(e.key==='Tab'){const region=$('.modal')||$('.sidebar.open');if(region)containFocus(e,region);}if(e.key==='Enter'&&e.target.id==='contract-search'){e.preventDefault();searchContracts();}});
document.addEventListener('change',async e=>{const t=e.target;if(t.id==='source-select'){state.source=t.value;state.selected=null;persist();render();}if(t.id==='chart-symbol'){state.selected=t.value;render();const h=selected();if(h&&credentialFor(h)&&!runtime.brokerCandles[key(h)])try{await loadCandles(h);render();}catch(e){toast(e.message,true);}}if(t.id==='op-filter'){state.opFilter=t.value;render();}if(t.id==='fno-underlying'){runtime.fno.epoch=(runtime.fno.epoch||0)+1;runtime.fno.results=[];runtime.fno.underlying=t.value;runtime.fno.contract=null;runtime.fno.quote=null;runtime.fno.candles=[];render();}if(t.id==='fno-broker'){runtime.fno.epoch=(runtime.fno.epoch||0)+1;runtime.fno.results=[];runtime.fno.broker=t.value;runtime.fno.contract=null;runtime.fno.quote=null;runtime.fno.candles=[];render();}if(t.id==='account-size'||t.id==='risk-percent'){const v=Number(t.value);if(t.id==='account-size'&&v>0)state.settings.accountSize=v;if(t.id==='risk-percent'&&v>0&&v<=2)state.settings.riskPercent=v;persist();render();}if(t.id==='holdings-file'&&t.files[0]){await importHoldingsFile(t);}if(t.id==='candles-file'&&t.files[0]){try{if(t.files[0].size>10*1024*1024)throw new Error('Please use a price-history CSV smaller than 10 MB.');const p=parseCSV(await t.files[0].text());for(const k of ['time','open','high','low','close','volume'])if(!p.headers.includes(k))throw new Error(`Missing required column: ${k}`);const bars=p.rows.map(r=>({time:r.time,...Object.fromEntries(['open','high','low','close','volume'].map(k=>[k,r[k]===''?NaN:Number(r[k])])),...(r.oi!==undefined&&r.oi!==''?{oi:Number(r.oi)}:{})})).sort((a,b)=>Date.parse(a.time)-Date.parse(b.time));const errors=validateCandles(bars);if(errors.length)throw new Error(errors.slice(0,3).join(' '));if(new Set(bars.map(b=>b.time.slice(0,10))).size!==bars.length)throw new Error('Daily history must have no more than one completed candle per date.');if(bars.length<20)throw new Error('Import at least 20 completed daily candles.');if(Date.parse(bars.at(-1).time)>Date.now())throw new Error('Future candles are not valid.');let h=runtime.importTarget;if(!h)throw new Error('Select a holding before importing prices.');if(h.source==='demo'){const a=ensureCsvAccount();h={...h,source:'csv',accountId:a.id,quantity:0,average_price:0};if(!state.holdings.some(x=>key(x)===key(h)))state.holdings.push(h);}state.imported[key(h)]={candles:bars,asOf:bars.at(-1).time,importedAt:new Date().toISOString(),isStale:true};setScope('account:'+h.accountId,false);state.selected=key(h);state.tab='overview';persist();render();toast(`Imported ${bars.length} daily candles for ${h.symbol}. CSV remains unverified research data.`);}catch(e){toast(e.message,true);}finally{t.value='';}}});
document.addEventListener('input',e=>{if(e.target.id==='holdings-search'){state.search=e.target.value;const table=$('.holdings-card tbody');table.innerHTML=visibleHoldings().filter(h=>`${h.symbol} ${h.name||''}`.toLowerCase().includes(state.search.toLowerCase())).map(h=>holdingRow(h,['portfolio','swing'].includes(state.tab))).join('')||'<tr><td colspan="7"><div class="empty-state">No holdings match your search.</div></td></tr>';}if(e.target.id==='contract-search')runtime.fno.query=e.target.value;});
document.addEventListener('submit',async e=>{const f=e.target;e.preventDefault();if(f.id==='connect-form'){await connectForm(f);return;}if(f.id==='thesis-form'){
 const fd=new FormData(f),t=Object.fromEntries(fd);
 for(const k of ['fairValue','earningsGrowth','minGrowth','debtEquity','maxDebt','minMonths','maxMonths'])t[k]=fd.get(k)===''?null:Number(fd.get(k));
 t.cashFlowPositive=fd.get('cashFlowPositive')==='true'?true:fd.get('cashFlowPositive')==='false'?false:null;
 if(!(t.minMonths>0)||!(t.maxMonths>=t.minMonths)||t.maxMonths>120){toast('Choose a valid planned window between 1 and 120 months.',true);return;}
 state.theses[f.dataset.id]=t;persist();render();toast('Thesis saved. Review the criteria and evidence dates.');return;
 }if(f.id==='holding-form'){const fd=new FormData(f),old=state.holdings.find(h=>key(h)===f.dataset.id);const h={...old,symbol:String(fd.get('symbol')).trim().toUpperCase(),exchange:String(fd.get('exchange')),quantity:Number(fd.get('quantity')),average_price:Number(fd.get('average_price')),token:String(fd.get('token')||'').trim()||undefined,accountId:old?.accountId||String(fd.get('accountId')||''),source:old?.source||accountById(String(fd.get('accountId')))?.broker||'csv'};if(!/^[A-Z0-9][A-Z0-9&_. -]{0,49}$/.test(h.symbol)||!(h.quantity>=0)||!Number.isFinite(h.quantity)||!(h.average_price>=0)||!Number.isFinite(h.average_price)||(h.quantity>0&&h.average_price<=0)){toast('Use nonnegative quantity and cost; an owned position needs a positive average price.',true);return;}if(!accountById(h.accountId)||accountById(h.accountId).broker==='demo'){toast('Select a real account for this holding.',true);return;}const duplicate=state.holdings.find(x=>key(x)===key(h)&&key(x)!==f.dataset.id);if(duplicate){toast('This holding already exists. Edit its quantity and average cost.',true);return;}if(old){const oldId=key(old);state.holdings=state.holdings.map(x=>key(x)===oldId?h:x);if(oldId!==key(h)&&state.imported[oldId]){state.imported[key(h)]=state.imported[oldId];delete state.imported[oldId];}}else state.holdings.push(h);setScope('account:'+h.accountId,false);state.selected=key(h);persist();closeModal();render();toast('Tracked stock saved.');if(credentialFor(h)){try{await loadCandles(h);render();}catch(err){toast(err.message,true);}}}if(f.id==='settings-form'){const fd=new FormData(f);state.settings={horizon:fd.get('horizon'),accountSize:Number(fd.get('accountSize')),riskPercent:Number(fd.get('riskPercent'))};persist();closeModal();render();toast('Research preferences updated.');}});
setInterval(()=>{if(document.hidden||state.tab==='longterm')return;if(state.tab==='fno'&&runtime.fno.contract)refreshFno(false);else if(['overview','portfolio','swing','family'].includes(state.tab)&&Object.keys(runtime.credentials).length)refreshMarket(false);},15000);
